# ------------------------------------------------------------------ patch140
# The fifteen-patch spacing bug was ONE CHARACTER: the log is CRLF on Windows, the
# client splits on LF, and the CR left on every FILE line becomes a newline when
# innerHTML parses it - a pre-wrap row with a trailing newline renders TWO lines
# tall. Spliced rows are built client-side without CR, which is why they alone
# were ever tight. The painter scrubs CR before anything else looks. Every read
# this gate and its author ever did in text mode silently hid the CR - so this
# check feeds the painter real CRLF and reads what the page would be handed.
check('text = String(text).split(String.fromCharCode(13)).join("");'
      in seg(JS, "function paintTail(", "function stepAt"),
      "the painter scrubs the carriage return before anything else looks")
_cr40 = None
try:
    import subprocess as _spc
    _rc40 = _spc.run(["node", "-e", "const src=require('fs').readFileSync(process.argv[1],'utf8');function sl(a,b){const i=src.indexOf(a);const j=src.indexOf(b,i);return src.slice(i,j).split(String.fromCharCode(13)).join('');}let code='';code+=sl('const SPK_MAG','const SAID_MARK_25');code+=sl('const SAID_MARK_25','/* A word boundary');code+=sl('const TERM_INS_KINDS','function paintTail(');code+=sl('function fixTree(text)','function hiddenProvs');code+=sl('function dropPanelProv(','function paintTail(');code+=sl('function paintTail(','function stepAt');globalThis.window=globalThis;const state={settings:{},routing:[]};let captured='';const el={set innerHTML(h){captured=h;},dataset:{},classList:{toggle:function(){},add:function(){},remove:function(){}},style:{}};const $=id=>id==='tail-dashboard'?el:null;const esc=s=>String(s==null?'':s);function termInsTtsOn(){return false;}function sizeTailEl(){}function paintThink(){}function markNewRows(){}function paintSpoken(l){return esc(l);}function paintTok(x){return esc(x);}function provMark(){return '';}function refTake(l){return {line:l,kind:'',id:''};}function refChip(){return '';}const MARK={provs:[],cast:[],rx:{}};const SPK_MAG='#ff5dc8',SPK_CY='#2ef2ff';function post(){}const ELEM={seg:{base:'#111'},segalt:{base:'#222'}};const SEAM_MARK=String.fromCodePoint(0x2042);function entInk(){return '';}const PAINT={name:'#ff5dc8',tag:'#2ef2ff',stamp:'#4dd8e6',said:'#f2c14e',quote:'#f0c674',think:'#c07ffb',num:'#ff7a6b',unit:'#4dd8e6',dim:'#8b93a3',kind:{}};eval(code);markNewRows=function(){};sizeTailEl=function(){};paintThink=function(){};paintSpoken=function(l){return esc(l);};paintTok=function(x){return esc(x);};refTake=function(l){return {line:l,kind:'',id:''};};refChip=function(){return '';};const CR=String.fromCharCode(13),NL=String.fromCharCode(10);const raw=['[05:44:11.10] M Meta [1237] 2942 / 53 tok 6636','[05:44:13.30] V Vision [1238] 843 / 179 tok 961'].join(CR+NL)+CR+NL;paintTail('dashboard', raw);console.log(JSON.stringify([captured.indexOf(CR)<0,(captured.match(/class=.tl./g)||[]).length]));", os.path.join(ROOT, "fleet-panel.py")],
                     capture_output=True, text=True, timeout=60)
    _cr40 = json.loads(_rc40.stdout.strip() or "null")
except Exception:
    _cr40 = None
if _cr40 is not None:
    check(_cr40[0] is True and _cr40[1] == 2,
          "run: CRLF input paints CR-free rows, one per line, trailing blank "
          "dropped - no row can stand two lines tall", str(_cr40))
else:
    check(False, "the CRLF run did not RUN - node or the snippet is broken")
check("min-height:1.3em" in seg(PAGE, ".tail .tbr, .tail .tbrend {", ".tail .tbr::before"),
      "and the branch connector joins the same rhythm instead of standing 1.6em")
