    time.sleep(0.05)
    fp.tts_thought_after_chunk("GateRace", None, 0.25)
    time.sleep(fp.th_start_lat() * 2 + 4 * (0.25 + fp.TH_CHUNK_GAP)
               + 2 * fp.TH_FIRE_PAD + 1.2)
    fp.tts_thought_make, fp.sse_notify, fp.calterm_log = _mk60, _no60, _cl60
