    fp.SSE_CLIENTS.clear(); fp.SSE_CLIENTS.update(_sv37)
    _pl37, _sp37, _tk37 = fp.panel_log, fp.tts_sample_path_for, fp.tts_take_path
    _sn37 = fp.sse_notify
    _cap37 = []
