# ---------------------------------------------------------- v3.76 patch38
section("v3.76 patch38: the vault repair")
# The 160-file disease from the v3.74 forensics finally gets its cure at the
# source: a scan and an in-place repair for the Local Voice Clips folder,
# beside the adoption path that already normalizes copies. Only over-claims
# are patients; originals are copied out before a byte moves.
_vv38 = seg(py, "def _vault_head_verdict(buf, size):", "\r\ndef ")
check("0xFFFFFFFF" in _vv38 and "csz > have" in _vv38
      and "riff > size - 8" in _vv38,
      "the verdict condemns the streaming writer's lie and every other over-claim")
check('return ("ok", off)' in _vv38
      and "legal trailing junk" in _vv38,
      "and leaves an honest or merely modest header alone")
_vs38 = seg(py, "def tts_vault_survey(vdir, cap=20000):", "\r\ndef ")
check('dirs[:] = [d for d in dirs if d != "_header-backup"]' in _vs38,
      "the walk never treats an original as a patient")
check('.lower().endswith(".wav")' in _vs38 and "return out, True" in _vs38,
      "wav files alone, and a capped walk says so instead of lying by omission")
_sc38 = seg(py, "def api_tts_vault_scan(body=None):", "\r\ndef ")
_rp38 = seg(py, "def api_tts_vault_repair(body=None):", "\r\ndef ")
check('"ttsVoiceDir"' in _sc38 and '"ttsVoiceDir"' in _rp38
      and "body.get(" not in _sc38 and "body.get(" not in _rp38,
      "both doors read the configured folder alone - never a caller path")
check("tts_vault_survey(vdir)" in _sc38 and "tts_vault_survey(vdir)" in _rp38,
      "one walker answers both doors, so they can never disagree")
check("if not os.path.exists(bak):" in _rp38
      and "the first copy is the original" in _rp38,
      "the backup is written before the patch, and the FIRST copy is the one kept")
check("f.seek(4)" in _rp38 and "(size - 8).to_bytes" in _rp38
      and "f.seek(doff + 4)" in _rp38 and "(size - (doff + 8)).to_bytes" in _rp38,
      "two fields are rewritten to the truth - RIFF size and data size, nothing else")
check('"/api/tts-vault-scan": api_tts_vault_scan,' in py
      and '"/api/tts-vault-repair": api_tts_vault_repair,' in py,
      "both doors stand in the table")
_rv38 = seg(py, 'REMOTE_POST_OK = {"/api/tail"', "}")
nin(_rv38, "tts-vault", "a remote page never rewrites files on the panel's disk")
check(py.count('["!v", "vault"],') == 2,
      "the row is declared in both tables like its cache neighbour",
      "%d found" % py.count('["!v", "vault"],'))
check('data-act="ttsVaultScan"' in JS and 'data-act="ttsVaultRepair"' in JS
      and 'id="tts-vaultline"' in JS,
      "two buttons and the line their answers land on")
_vr38 = seg(JS, "function vaultRepair() {", "function audioCacheShow")
check('"Repair broken WAV headers?"' in _vr38 and "r.value !== true" in _vr38,
      "the repair asks first, through the same dialog the cache clear uses")
check("nothing to repair - every header is honest" in _vr38
      and "nothing to repair - every header is honest" in _rp38,
      "and a clean vault is said in the same words on both sides of the wire")
try:
    import struct as _st38
    def _wav38(dd, rd=None, pre=b"", pay=b"\x00" * 100):
        body = (b"fmt " + _st38.pack("<I", 16) + b"\x00" * 16 + pre
                + b"data" + _st38.pack("<I", dd) + pay)
        return b"RIFF" + _st38.pack("<I", rd if rd is not None else 4 + len(body)) \
               + b"WAVE" + body
    _cl38 = _wav38(100)
    _do38 = _cl38.index(b"data")
    _ls38 = _wav38(100, pre=b"LIST" + _st38.pack("<I", 4) + b"INFO")
    check(fp._vault_head_verdict(_cl38, len(_cl38)) == ("ok", _do38)
          and fp._vault_head_verdict(_wav38(0xFFFFFFFF), len(_cl38))[0] == "broken"
          and fp._vault_head_verdict(_wav38(101), len(_cl38))[0] == "broken"
          and fp._vault_head_verdict(_wav38(98), len(_cl38))[0] == "ok"
          and fp._vault_head_verdict(_wav38(100, rd=0xFFFFFFFF), len(_cl38))[0] == "broken"
          and fp._vault_head_verdict(_ls38, len(_ls38)) == ("ok", _ls38.index(b"data"))
          and fp._vault_head_verdict(b"JUNK" + b"\x00" * 40, 44)[0] == "odd"
          and fp._vault_head_verdict(b"RIFF\x00\x00\x00\x00WAVE", 12)[0] == "odd",
          "run: the verdict matrix - the 0xFFFFFFFF classic and a plain over-claim "
          "condemned, an honest header and a modest under-claim spared, a LIST "
          "chunk walked past, junk and a stub called odd")
    _bk38 = bytearray(_wav38(0xFFFFFFFF))
    _sz38 = len(_bk38)
    _bk38[4:8] = (_sz38 - 8).to_bytes(4, "little")
    _bk38[_do38 + 4:_do38 + 8] = (_sz38 - (_do38 + 8)).to_bytes(4, "little")
    check(fp._vault_head_verdict(bytes(_bk38), _sz38) == ("ok", _do38),
          "run: the repair's two-field math heals exactly what the verdict condemns")
except Exception as _e38x:
    check(False, "the patch38 runs did not RUN (patch38)", str(_e38x)[:140])


