# ---------------------------------------------------------- v3.76 patch79
section("v3.76 patch79: the panel's folders, and the padlock that opens them")
# Every folder the panel writes into now has a default under its own directory,
# and is locked to it. Locked is not permanent: the padlock beside the field
# opens it, and while it is open the panel stops putting the folder back - which
# is the whole meaning of unlocking. The arrow beside it puts the folder back,
# to the panel's own or to any path it has had before.
check('"llamacppPath": ("llama.cpp",),' in py and '"modelsDir": ("models",),' in py
      and '"launcherDir": ("launchers",),' in py and '"logDir": ("logs",),' in py
      and '"yamlOutDir": ("providerYAML",),' in py,
      "the five new folders default under the panel's own directory")
_fd79 = seg(py, "def tts_fix_dirs", "def higgs_paths")
check("free = dir_unlocked(st)" in _fd79 and "if key in free:" in _fd79
      and "continue                     # the user took charge of this one" in _fd79,
      "and a LOCKED one is put back, while an unlocked one is left exactly as "
      "the user set it - otherwise unlocking would mean nothing")
check("def dir_unlocked(st):" in py and "def dir_history(st):" in py
      and "def dir_history_push(st, key, path):" in py,
      "which folders are open, and where each has been, are both remembered")
_dh79 = seg(py, "def dir_history_push", "def tts_fixed_dir")
check("[p for p in (h.get(key) or []) if p != path]" in _dh79
      and "[:100]" in _dh79,
      "newest first, no repeats, and capped")
check("def api_dir_lock(body=None):" in py and "def api_dir_revert(body=None):" in py
      and "def api_dir_info(body=None):" in py
      and '"/api/dir-lock": api_dir_lock,' in py,
      "three doors: open it, put it back, and say where it has been")
_dl79 = seg(py, "def api_dir_lock", "def api_dir_revert")
check('if key not in TTS_FIXED_DIRS:' in _dl79,
      "and none of them will touch a key the panel does not own")
_dr79 = seg(py, "def api_dir_revert", "def api_dir_info")
check("dir_history_push(st, key, st.get(key) or \"\")" in _dr79,
      "the path being left is remembered BEFORE it is replaced")
check("free.discard(key)                # back to the panel's, so back under lock" in _dr79,
      "and going back to the panel's own puts it back under lock, because it is "
      "the panel's folder again")
check("function dirFree(k)" in JS and "function dirLockBtns(k)" in JS,
      "the field shows which state it is in")
check("String.fromCodePoint(open ? 128275 : 128274)" in JS
      and "a lone surrogate is not the emoji" in JS,
      "with a padlock written as a CODE POINT - a \\uD83D\\uDD12 escape is read "
      "by python as half a character, and half a character is a broken one")
check('TTS_LOCKED_DIRS.indexOf(f[0]) >= 0 && !dirFree(f[0])' in JS
      and 'TTS_LOCKED_DIRS.indexOf(k) >= 0 && !dirFree(k)' in JS,
      "and both pages grey the field only while it is locked")
_ra79 = seg(JS, "function dirRevertAsk", "function cudaLinePick")
check("Currently" in _ra79 and "The panel\u2019s own" in _ra79
      and "Used before" in _ra79 and 'class="dirhist"' in _ra79,
      "the revert dialog shows where it is, where it would go, and where it "
      "has been")
check("hist = (info.history || []).filter(p => p && p !== info.now)" in _ra79,
      "without offering the path it is already on")
check(".dirhist::-webkit-scrollbar-thumb" in py and "max-height:44vh" in py,
      "and the history scrolls, with a bar to drag")
_ha79 = seg(JS, 'if (d.act === "dirLock")', 'if (d.act === "llamaPick")')
check("await uiConfirm(" in _ha79 and "nothing is moved or deleted" in _ha79
      and "if (!open)" in _ha79,
      "unlocking asks first, and says what it will not do - re-locking does not "
      "ask, because it changes nothing")
try:
    # tts_fix_dirs CREATES the folders it fixes, so the paths are computed here
    # instead - the gate leaves no trace, including no empty directories
    _def79 = dict((_k, fp.tts_fixed_dir(_k)) for _k in
                  ("llamacppPath", "modelsDir", "launcherDir", "logDir",
                   "yamlOutDir"))
    _inside79 = all(_v.startswith(fp.STACK) for _v in _def79.values())
    _mk79 = os.makedirs
    _elsewhere79 = _tf50.mkdtemp()
    try:
        os.makedirs = lambda *a, **k: None      # and none while these run either
        fp.os.makedirs = os.makedirs
        _lk79 = {"modelsDir": _elsewhere79}
        fp.tts_fix_dirs(_lk79)
        _put79 = _lk79["modelsDir"] == fp.tts_fixed_dir("modelsDir")
        _fr79 = {"modelsDir": _elsewhere79,
                 "dirUnlocked": json.dumps(["modelsDir"])}
        fp.tts_fix_dirs(_fr79)
        _left79 = _fr79["modelsDir"] == _elsewhere79
    finally:
        os.makedirs = _mk79
        fp.os.makedirs = _mk79
        shutil.rmtree(_elsewhere79, ignore_errors=True)
    _hs79 = {}
    for _p79 in ("one", "two", "one"):
        fp.dir_history_push(_hs79, "modelsDir", _p79)
    _order79 = fp.dir_history(_hs79)["modelsDir"]
    for _i79 in range(150):
        fp.dir_history_push(_hs79, "modelsDir", "p%d" % _i79)
    _cap79 = len(fp.dir_history(_hs79)["modelsDir"])
    check(_inside79 and _put79 and _left79
          and _order79 == ["one", "two"] and _cap79 == 100,
          "run: every default sits under the panel's folder; a locked one is "
          "put back and an unlocked one is not; history is newest-first, "
          "de-duplicated and capped at a hundred",
          str([_inside79, _put79, _left79, _order79, _cap79]))
except Exception as _e79x:
    check(False, "the patch79 run did not RUN", str(_e79x)[:140])

# ---------------------------------------------------------- v3.76 patch80
section("v3.76 patch80: sorting models by what their headers say")
# The only feature in this panel that MOVES the user's files, so it is built in
# that order: a plan that can be read, then a move that re-points every card
# naming a file it moved. A header that does not say what a model is leaves the
# file alone - sorting on a guess moves a file for a reason nobody can check.
check('MODEL_SORT_KINDS = {"main": "LLM", "draft": "MTP", "vision": "Vision"}' in py,
      "three kinds, named as the user names them")
_ms80 = seg(py, "def model_sort_target", "def model_sort_plan")
check("if not top:\r\n        return ()" in _ms80,
      "a model whose header does not say what it is is not sorted at all")
check('fam = _sort_word(f.get("arch") or "")' in _ms80
      and "the label is prose for a human" in _ms80,
      "the family comes from the ARCHITECTURE - arch_label is prose and makes a "
      "ridiculous folder")
check('size = _sort_word(f.get("size") or "")' in _ms80
      and 'return (top, fam) if not size else (top, fam, size)' not in _ms80,
      "and the size from the header's own size label")
_sw80 = seg(py, "def _sort_word", "def model_sort_target")
check('re.sub(r"[^A-Za-z0-9.]+"' in _sw80 and "0.6B" in _sw80,
      "dots survive, because 0.6B folded to 06B is a different number")
_mp80 = seg(py, "def model_sort_plan", "def tts_fix_model")
check("Nothing is moved here" in _mp80 and '"slots": users' in _mp80,
      "the plan moves nothing and names the cards that point at each file")
_ma80 = seg(py, "def model_sort_apply", "def api_model_sort")
check('if os.path.exists(dst):' in _ma80
      and '"why": "something is already there"' in _ma80,
      "a file that would land on another is left alone and reported")
check('for key in ("model", "vision", "draft"):' in _ma80
      and "p[key] = dst" in _ma80,
      "and every card naming a moved file is re-pointed - model, vision and "
      "draft alike - in the same step as the move")
check('"/api/model-sort": api_model_sort,' in py and '"modelAutoSort": "off"' in py,
      "the door exists and the feature ships OFF")
_sa80 = seg(JS, "function modelSortAsk", "function dirRevertAsk")
check("esc(ttsBaseName(p.from))" in _sa80,
      "the plan names files with the basename helper - a backslash class has to "
      "survive the page string AND the JS parser, and that is settled already")
check("Files are moved, not " in _sa80 and "id=\"msort-go\"" in _sa80,
      "it says what it will do before the button that does it")
_hs80 = seg(JS, 'if (d.act === "modelSort")', 'if (d.act === "dirLock")')
check('post("/api/model-sort", {})' in _hs80
      and "if (!(await modelSortAsk(r.plan || []))) return;" in _hs80
      and 'post("/api/model-sort", { run: "1" })' in _hs80,
      "and the plan is asked for, shown, and only then run")
try:
    def _mk80(arch, size, blocks=3):
        _kvs = [("general.architecture", arch), ("general.size_label", size)]
        b = (b"GGUF" + _st50.pack("<I", 3) + _st50.pack("<Q", blocks)
             + _st50.pack("<Q", len(_kvs) + 1))
        for _k, _v in _kvs:
            b += _kv50(_k, _v)
        _bc = arch + ".block_count"
        b += (_st50.pack("<Q", len(_bc)) + _bc.encode() + _st50.pack("<I", 4)
              + _st50.pack("<I", blocks))
        for _i in range(blocks):
            _nm = ("blk.%d.weight" % _i).encode()
            b += (_st50.pack("<Q", len(_nm)) + _nm + _st50.pack("<I", 1)
                  + _st50.pack("<Q", 4096 * 4096) + _st50.pack("<I", 8)
                  + _st50.pack("<Q", 0))
        return b
    _sv80 = fp.save_config
    _ok80, _ot80 = fp._KIND["file"], fp._TKIND["file"]
    _om80, _on80 = fp._KIND["map"], fp._TKIND["map"]
    try:
        fp.save_config = lambda c: None
        with _tf50.TemporaryDirectory() as _d80:
            fp._KIND["file"] = os.path.join(_d80, "k.json")
            fp._TKIND["file"] = os.path.join(_d80, "t.json")
            fp._KIND["map"] = None
            fp._TKIND["map"] = None
            _root80 = os.path.join(_d80, "models")
            os.makedirs(_root80)
            _a80 = os.path.join(_root80, "gemma-4-31B-it-scotoma-2.gguf")
            _b80 = os.path.join(_root80, "qwen3-0.6b-draft.gguf")
            with open(_a80, "wb") as _f:
                _f.write(_mk80("gemma4", "31B"))
            with open(_b80, "wb") as _f:
                _f.write(_mk80("qwen3", "0.6B"))
            _cfg80 = {"settings": {"modelsDir": _root80},
                      "slots": [{"id": "s1", "title": "Server 1",
                                 "params": {"model": _a80, "draft": _b80}}]}
            _plan80 = fp.model_sort_plan(_cfg80)
            _still80 = os.path.isfile(_a80)          # the plan moved nothing
            _why80 = sorted(_p["why"] for _p in _plan80)
            _who80 = [_p["slots"] for _p in _plan80
                      if _p["from"] == _a80][0]
            _res80 = fp.model_sort_apply(_cfg80)
            _pm80 = _cfg80["slots"][0]["params"]
            _landed80 = os.path.isfile(os.path.join(
                _root80, "LLM", "Gemma4", "31B",
                "gemma-4-31B-it-scotoma-2.gguf"))
    finally:
        fp.save_config = _sv80
        fp._KIND["file"], fp._TKIND["file"] = _ok80, _ot80
        fp._KIND["map"], fp._TKIND["map"] = _om80, _on80
    check(_still80 and _landed80
          and _why80 == ["LLM/Gemma4/31B", "MTP/Qwen3/0.6B"]
          and _who80 == ["Server 1"]
          and len(_res80["moved"]) == 2 and not _res80["skipped"]
          and _pm80["model"].endswith(os.path.join("LLM", "Gemma4", "31B",
                                                   "gemma-4-31B-it-scotoma-2.gguf"))
          and _pm80["draft"].endswith(os.path.join("MTP", "Qwen3", "0.6B",
                                                   "qwen3-0.6b-draft.gguf")),
          "run: the plan names both moves and the card that uses one, and moves "
          "nothing; the apply puts each under kind/family/size and re-points the "
          "card's model AND draft",
          str([_still80, _landed80, _why80, _who80,
               len(_res80["moved"]), _pm80["model"][-40:]]))
except Exception as _e80x:
    check(False, "the patch80 run did not RUN", str(_e80x)[:140])

# ---------------------------------------------------------- v3.76 patch81
section("v3.76 patch81: defaults, not overrides")
# patch79 gave five folders defaults under the panel's directory AND put them
# back on every config read. For a new install that is right; for someone
# upgrading it replaced the paths they had chosen, the first time the panel
# loaded. A default is what you get when you have not said - it is not an
# instruction to forget what you did say.
check('DIR_ADOPTED_P79 = ("llamacppPath", "modelsDir", "launcherDir", "logDir",' in py
      and "these\r\n# five belonged to the user first" in py,
      "the five folders taken over at patch79 are named, and separated from the "
      "four the panel has owned since patch56")
_ae81 = seg(py, "def dir_adopt_existing", "def dir_unlocked")
check('if str(st.get("dirMigrated") or ""):' in _ae81 and 'st["dirMigrated"] = "1"' in _ae81,
      "the adoption happens once, on the first read after upgrading")
check('if cur and cur != tts_fixed_dir(key):' in _ae81 and "free.add(key)" in _ae81,
      "a folder already set to something else is marked as the user's, so "
      "nothing puts it back")
_fs81 = seg(py, "def _dir_from_slots", "def dir_adopt_existing")
check("return seen.pop() if len(seen) == 1 else \"\"" in _fs81
      and "one guess from disagreeing evidence is worse than none" in _fs81,
      "and where patch79 already replaced one, the slots are read back - but "
      "only when they all agree")
check("if dir_adopt_existing(cfg):" in py
      and before(py, "if dir_adopt_existing(cfg):", "    if tts_fix_dirs(st):"),
      "the adoption runs BEFORE the put-back, or the put-back would win")
try:
    _D81 = fp.tts_fixed_dir
    # A: upgrading, the user's paths are still in the config
    _cfgA = {"settings": {"llamacppPath": "u-llama", "modelsDir": "u-models",
                          "launcherDir": "u-launchers", "logDir": "",
                          "yamlOutDir": ""}}
    fp.dir_adopt_existing(_cfgA)
    fp.tts_fix_dirs(_cfgA["settings"])
    _stA = _cfgA["settings"]
    _keptA = (_stA["llamacppPath"] == "u-llama"
              and _stA["modelsDir"] == "u-models"
              and _stA["launcherDir"] == "u-launchers"
              and _stA["logDir"] == _D81("logDir"))
    _freeA = sorted(json.loads(_stA["dirUnlocked"]))
    # B: patch79 already replaced it - the slots still name the real folder
    with _tf50.TemporaryDirectory() as _d81:
        _real81 = os.path.join(_d81, "real-models")
        os.makedirs(_real81)
        _m81 = os.path.join(_real81, "a.gguf")
        with open(_m81, "wb") as _f:
            _f.write(b"x")
        _cfgB = {"settings": {"modelsDir": _D81("modelsDir"), "dirUnlocked": "[]"},
                 "slots": [{"id": "s1", "params": {"model": _m81}}]}
        fp.dir_adopt_existing(_cfgB)
        fp.tts_fix_dirs(_cfgB["settings"])
        _gotB = _cfgB["settings"]["modelsDir"] == _real81
        # and NOT when the slots disagree
        _other81 = os.path.join(_d81, "other")
        os.makedirs(_other81)
        _m82 = os.path.join(_other81, "b.gguf")
        with open(_m82, "wb") as _f:
            _f.write(b"x")
        _cfgD = {"settings": {"modelsDir": _D81("modelsDir"), "dirUnlocked": "[]"},
                 "slots": [{"id": "s1", "params": {"model": _m81}},
                           {"id": "s2", "params": {"model": _m82}}]}
        fp.dir_adopt_existing(_cfgD)
        _gotD = _cfgD["settings"]["modelsDir"] == _D81("modelsDir")
    # C: a fresh install takes the defaults
    _cfgC = {"settings": {}}
    fp.dir_adopt_existing(_cfgC)
    fp.tts_fix_dirs(_cfgC["settings"])
    _gotC = (_cfgC["settings"]["modelsDir"] == _D81("modelsDir")
             and json.loads(_cfgC["settings"]["dirUnlocked"]) == [])
    check(_keptA and _freeA == ["launcherDir", "llamacppPath", "modelsDir"]
          and _gotB and _gotD and _gotC,
          "run: an upgrade keeps every folder the user had chosen and adopts it "
          "as theirs; one already replaced is recovered from the slots, but not "
          "when the slots disagree; and a fresh install takes the defaults",
          str([_keptA, _freeA, _gotB, _gotD, _gotC]))
except Exception as _e81x:
    check(False, "the patch81 run did not RUN", str(_e81x)[:140])

# ---------------------------------------------------------- v3.76 patch82
section("v3.76 patch82: a digest to check against, and n-gram beside MTP")
# The chooser showed a sha256 as a grey line, which is a fact nobody reads. It
# is the one thing that decides whether an executable can be trusted, so it is
# a verdict now - and a build that publishes none cannot be installed from here
# at all. Beside that: llama.cpp takes --spec-type as a comma-separated list and
# mixes a draft-based type with a draftless one, so n-gram speculation runs
# ALONGSIDE an MTP head rather than instead of it.
_cp82 = seg(JS, "function cudaLinePick", "async function llamaInstall")
check('class="cudasha ok">\u2705 sha256 ' in _cp82
      and 'class="cudasha bad">\u274C no sha256 published' in _cp82,
      "the digest is a verdict - green with a tick when there is one, red with "
      "a cross when there is not")
check("A digest here is not a file that has been checked" in _cp82,
      "and it says what it MEANS: the download will be checked against this, "
      "not that a file has already passed")
check("const okSha = !!((A[chosen] || {}).sha);" in _cp82
      and 'go.style.display = okSha ? "" : "none";' in _cp82
      and 'id="cudapick-why"' in _cp82,
      "a build with no digest cannot be installed from here, and the reason is "
      "shown where the button was")
check(".cudasha.ok { color:var(--ok); }" in py and ".cudasha.bad { color:#ff5d5d; }" in py,
      "in the colours that say it without being read")
# --- n-gram speculation
check('("ngram",     "N-gram speculation",  "sel",  "off",' in py
      and '"ngram-mod", "ngram-simple", "ngram-map-k",' in py,
      "the card offers every draftless type llama.cpp names, and none by default")
_bp82 = seg(py, "def build_param_launcher", "def ps1_args_span")
check("NGRAM_FLAGS = {" in _bp82
      and '"ngramSizeN": "--spec-ngram-simple-size-n"' in _bp82
      and '"ngramSizeN": "--spec-ngram-map-k4v-size-n"' in _bp82,
      "one row on the card becomes the flag that TYPE actually takes - upstream "
      "names them per implementation")
check('_ngflags = NGRAM_FLAGS.get(_ng, {}) if _ng and _ng != "off" else {}' in _bp82
      and "continue                   # not a setting this n-gram type has" in _bp82,
      "and a setting the chosen type does not have is not written at all")
check('args[_i] = (_g, _f, (str(_v) + "," + _ngt) if _v else _ngt)' in _bp82
      and "it would be whichever the parser saw last" in py,
      "--spec-type is ONE flag with a list - two of them would be whichever the "
      "parser saw last, not a mixture")
try:
    _cfg82 = {"settings": dict(fp.DEF_SETTINGS)}
    _cfg82["settings"]["llamacppPath"] = "C:/llama"

    def _spec82(params):
        _s = {"id": "s1", "title": "S1", "port": "5001",
              "params": dict({"model": "C:/m.gguf"}, **params)}
        _txt = fp.build_param_launcher(_cfg82, _s, "C:/x.ps1")
        _txt = _txt if isinstance(_txt, str) else str(_txt)
        return [_l.strip() for _l in _txt.splitlines() if "spec" in _l]
    _mtp82 = _spec82({"draft": fp.DRAFT_BUILTIN})
    _both82 = _spec82({"draft": fp.DRAFT_BUILTIN, "ngram": "ngram-mod",
                       "ngramMatch": "24", "ngramMin": "24", "ngramMax": "32"})
    _simple82 = _spec82({"ngram": "ngram-simple", "ngramSizeN": "12",
                         "ngramSizeM": "64", "ngramHits": "1"})
    _cache82 = _spec82({"ngram": "ngram-cache", "ngramSizeN": "12"})
    check('"--spec-type", "draft-mtp"' in " ".join(_mtp82)
          and '"--spec-type", "draft-mtp,ngram-mod"' in " ".join(_both82)
          and '"--spec-ngram-mod-n-max", "32"' in " ".join(_both82)
          and '"--spec-ngram-simple-size-n", "12"' in " ".join(_simple82)
          and "ngram-mod" not in " ".join(_simple82)
          and '"--spec-type", "ngram-cache"' in " ".join(_cache82)
          and "size-n" not in " ".join(_cache82),
          "run: n-gram rides alongside MTP on one --spec-type, each type gets "
          "the flags it actually has, and a type with none gets none",
          str([_both82[:1], _simple82[:2], _cache82]))
except Exception as _e82x:
    check(False, "the patch82 run did not RUN", str(_e82x)[:140])

# ---------------------------------------------------------- v3.76 patch83
section("v3.76 patch83: draftless speculation, beneath the drafting block")
# Three corrections and a name. The card's rows were only tight BELOW the load
# mode row, so everything above it - including the CPU rows either side of it -
# read as a different design. The n-gram rows belong under Speculative Decoding,
# which is written by hand at the END of the card rather than driven by the
# group order, so no group name could ever put them there. And they are not
# "Model" settings: they are speculation that needs no model at all.
check("const tight = true;" in JS and "was never a decision" in JS,
      "every row is spaced alike - the old rule only tightened rows below the "
      "load mode row, which left the CPU block split across both")
check('"ngramMatch": "Draftless speculation"' in py
      and "a group name could never have put them there" in py,
      "the group names their section in the LAUNCHER, and says why it cannot "
      "place them on the card")
check("const NGRAM_KEYS =" in JS
      and "NGRAM_KEYS.indexOf(d.key) < 0" in JS,
      "and are kept out of the loop that draws the groups")
check("h += ngramRows(s, p);" in JS,
      "they are drawn after the Speculative Decoding block instead, which is "
      "where they belong and where a group name could not reach")
_nr83 = seg(JS, "function ngramRows", "// ITEM 8:")
# retold p90: the same foldable heading the rest of the card uses
check('pgrpHead(s.id, "Draftless speculation")' in _nr83,
      "under a heading that says what they are - no model, so not Model")
check('const MOD = ["ngramMatch", "ngramMin", "ngramMax"];' in _nr83
      and 'const MAP = ["ngramSizeN", "ngramSizeM", "ngramHits"];' in _nr83
      and 'kind === "off" || kind === "ngram-cache" ? []' in _nr83,
      "each method shows the numbers it actually takes, and the two that take "
      "none show none")
check("const TPL = { dense:" in _nr83 and "moe:   {" in _nr83
      and "const locked = !!(tpl && tpl[k] !== undefined);" in _nr83,
      "a template fills its three and locks them")
check("const v = locked ? tpl[k] : val(k);" in _nr83,
      "showing what will RUN, not what is stored underneath")
check("def ngram_template_values(params):" in py
      and "a template that overwrote them would be a" in py,
      "and the stored numbers are never overwritten, so user hands them back")
check('NGRAM_TEMPLATES = {' in py
      and '"dense": {"ngramMatch": "24", "ngramMin": "16", "ngramMax": "32"}' in py
      and '"moe": {"ngramMatch": "24", "ngramMin": "48", "ngramMax": "64"}' in py,
      "the two templates carry the numbers llama.cpp's own guidance implies - "
      "long drafts for MoE, less for dense")
check("the dense figures are this panel's reading of that" in py,
      "and the panel says which of those numbers are upstream's and which are "
      "its own reading")
try:
    _cfg83 = {"settings": dict(fp.DEF_SETTINGS)}
    _cfg83["settings"]["llamacppPath"] = "C:/llama"

    def _mod83(params):
        _s = {"id": "s1", "title": "S1", "port": "5001",
              "params": dict({"model": "C:/m.gguf", "ngram": "ngram-mod"},
                             **params)}
        _txt = fp.build_param_launcher(_cfg83, _s, "C:/x.ps1")
        _txt = _txt if isinstance(_txt, str) else str(_txt)
        return " ".join(_l.strip() for _l in _txt.splitlines()
                        if "ngram-mod-n" in _l)
    _own83 = {"ngramMatch": "30", "ngramMin": "40", "ngramMax": "50"}
    _u83 = _mod83(dict(_own83, ngramTpl="user"))
    _d83 = _mod83(dict(_own83, ngramTpl="dense"))
    _m83 = _mod83(dict(_own83, ngramTpl="moe"))
    _back83 = _mod83(dict(_own83, ngramTpl="user"))
    check('"--spec-ngram-mod-n-min", "40"' in _u83
          and '"--spec-ngram-mod-n-min", "16"' in _d83
          and '"--spec-ngram-mod-n-max", "32"' in _d83
          and '"--spec-ngram-mod-n-min", "48"' in _m83
          and '"--spec-ngram-mod-n-max", "64"' in _m83
          and _back83 == _u83,
          "run: a template writes ITS numbers into the launcher and leaves the "
          "user's alone underneath - going back to user returns them unchanged",
          str([_u83[-30:], _d83[-30:], _m83[-30:]]))
except Exception as _e83x:
    check(False, "the patch83 run did not RUN", str(_e83x)[:140])

# ---------------------------------------------------------- v3.76 patch84
section("v3.76 patch84: the draftless rows wear the card's own clothes")
# They were drawn with hand-written markup that merely resembled a card row:
# white labels instead of the dim ones, an inert [--flag] instead of the
# reference link every other setting has, and selects wider than the number
# fields beside them. The cause was one line - SPEC_GUIDE and the link builder
# were declared INSIDE the drafting block, so the draftless rows could not reach
# them and something similar-looking got written instead.
check("const SPEC_GUIDE = {" in JS
      and before(JS, "const SPEC_GUIDE = {", "function ngramRows"),
      "the guide map is reachable by both halves of speculative decoding")
check("function specRef(flag) {" in JS,
      "and so is the one builder that turns a flag into a reference link")
_sg84 = seg(JS, "const SPEC_GUIDE = {", "};")
check('"--spec-ngram-mod-n-match": "N-gram lookup length"' in _sg84
      and '"--spec-ngram-*-size-n": "N-gram key length"' in _sg84
      and '"--spec-type": "N-gram speculation"' in _sg84,
      "every draftless flag has an entry, so every one of them LINKS")
_nr84 = seg(JS, "function ngramRows", "// ITEM 8:")
check('\'><span class="plab hint">\' + esc(d.label || k)' in _nr84
      and "'</span><span class=\"pctl\">' + ctl + '</span></div>'" in _nr84,
      "the rows use the card's own shape - plab and pctl, not a hand-written "
      "label that only looks like one")
check("Hand-rolled markup is how these came out white and uneven" in _nr84,
      "and say why, because the resemblance is what made it hard to see")
check('k === "ngramTpl" ? "" : specRef(d.flag || "")' in _nr84,
      "the template row shows no flag - it writes none, it fills the three "
      "rows below it")
check('\'<select class="pnum" data-act="slotParam" data-id="\' + s.id' in _nr84,
      "and its dropdowns are the width of the number fields beside them")
check('{"opts": ["user specified", "dense", "moe"]},' in py
      and '"sel",  "user specified",' in py,
      "the first option says what it means - user SPECIFIED, not a placeholder")
check('or "user specified")' in py,
      "and the panel looks for that same value, not the old one")
try:
    _js84 = JS
    _a84 = _js84.index("const SPEC_GUIDE")
    _b84 = _js84.index("// ITEM 8:")
    _drv84 = """
var esc = function (s) { return String(s); };
var pgSlug = function (s) {
  return String(s).toLowerCase().replace(/[^a-z0-9]+/g, "-");
};
var defs = [
  { key: "ngram", label: "N-gram speculation", flag: "--spec-type",
    kind: "sel", def: "off", opt: { opts: ["off", "ngram-mod"] } },
  { key: "ngramTpl", label: "N-gram template", flag: "--spec-type",
    kind: "sel", def: "user specified",
    opt: { opts: ["user specified", "dense", "moe"] } },
  { key: "ngramMatch", label: "N-gram lookup length",
    flag: "--spec-ngram-mod-n-match", kind: "num", def: "24", opt: {} },
  { key: "ngramMin", label: "N-gram draft, minimum",
    flag: "--spec-ngram-mod-n-min", kind: "num", def: "48", opt: {} },
  { key: "ngramMax", label: "N-gram draft, maximum",
    flag: "--spec-ngram-mod-n-max", kind: "num", def: "64", opt: {} }];
var state = { paramDefs: defs, settings: { cardFold: "{}" } };
var pgrpFold = null;
var pgrpKey = function (sid, g) { return sid + "|" + g; };
var pgrpShut = function () { return false; };
var pgrpHead = function (sid, g, extra) {
  return '<div class="pgrp pgrpfold"><svg class="pgrparrow"></svg>'
       + g + (extra || "") + '</div>';
};
""" + _js84[_a84:_b84].replace("const SPEC_GUIDE", "var SPEC_GUIDE")\
                      .replace("function specRef", "var specRef = function")\
                      .replace("function ngramRows", "var ngramRows = function") + """
var h = ngramRows({ id: "s1" },
                  { ngram: "ngram-mod", ngramTpl: "user specified" });
var links = (h.match(/class="pref" data-act="paramGuide"/g) || []).length;
var plain = (h.match(/class="pref" style="cursor:default"/g) || []).length;
var wide = (h.match(/<select class="pnum"/g) || []).length;
var hand = /<label>/.test(h);
var locked = ngramRows({ id: "s1" },
                       { ngram: "ngram-mod", ngramTpl: "dense" });
var lock = (locked.match(/pdim/g) || []).length;
process.stdout.write([links, plain, wide, hand, lock].join(","));
"""
    _r84 = _sp40.run(["node", "-e",
                      "eval(require('fs').readFileSync(0,'utf8'))"],
                     input=_drv84.encode(), capture_output=True, timeout=30)
    check(_r84.stdout.decode().strip() == "4,0,2,false,3",
          "run: every flag on the row links to its reference, the template row "
          "carries none, both dropdowns are the number-field width, no "
          "hand-written label survives, and a template locks its three",
          _r84.stdout.decode()[:80] + _r84.stderr.decode()[:80])
except Exception as _e84x:
    check(False, "the patch84 run did not RUN", str(_e84x)[:140])

# ---------------------------------------------------------- v3.76 patch85
section("v3.76 patch85: the row that failed is the row that says so")
# From the owner's own two failures. The first - a deliberate over-context test -
# was an SWA cache that could not be allocated, and the report blamed Compute,
# because the OOM marker went to the next CORE row still awaiting a value and
# kvSwa is not core. The second never said "memory" at all: the card reported
# 0 MiB free and the drafter died with "invalid vector subscript", which reads
# like a corrupt file and is not one.
check('"oomKey": "", "oomMiB": 0.0,' in py and '"oomWhat": ""' in py
      and '"noRoom": False' in py,
      "the reader records WHICH buffer failed, how big it was, and whether the "
      "card had already said it was full")
_vr85 = seg(py, "def slot_vram_report_text", "SLOT_LAUNCH_AT = {}")
check('out["oomKey"] = "kvSwa" if _kvw == "swa" else "kv"' in _vr85,
      "a failed KV cache is attributed to the one being BUILT - the reader "
      "already tracks which of the two that is")
check('out["noRoom"] and "failed to load draft model" in low' in _vr85
      and 'out["oomKey"] = out["oomKey"] or "draftGpu"' in _vr85,
      "and a drafter that failed after the card reported nothing free is an "
      "out-of-memory, whatever llama.cpp called it")
check("const oomKey = r.oomKey || \"\";" in JS
      and "(oomKey ? key === oomKey : (core && key === nextKey))" in JS,
      "the report marks THAT row, and only falls back to the old guess when the "
      "log did not say")
check('the card had 0 MiB free when the ' in JS,
      "with a line naming the thing that had nowhere to go")
# --- and compute stays summed, with the reason written down
check('out[_k] += float(m.group(2))' in _vr85
      and "broke a case that was measured to fix one that" in _vr85,
      "compute buffers are SUMMED - one per graph, all held at once - and the "
      "note says why the patch that briefly replaced them was wrong")
# --- and the report says which run it is about
check('_VR_SESS_RX = re.compile' in py and '_VR_MODEL_RX = re.compile' in py
      and '(.+?\\.gguf)' in py,
      "the run's model and launch time are read from the log itself, and the "
      "path stops at the extension because llama.cpp writes a version after it")
check(".vrow.vhdr .vlab" in py, "styled as its own line")
try:
    # BEHAVIOURAL: a textual pin on the row() call passes while the branch that
    # reaches it is disabled - the name of a feature is not the feature
    _a86 = JS.index("function vramModel")
    _b86 = JS.index("function ", JS.index("function vramModel") + 20)
    _hdr86 = """
var esc = function (s) { return String(s); };
var slotBusy = {}, vramAnswered = {}, vramWhy = {};
var VRAM_ROWS = [["weightsGpu", "Weights", 1], ["mmprojGpu", "Projector", 0],
  ["draftGpu", "Draft weights", 0], ["kv", "KV cache", 1],
  ["kvSwa", "SWA cache", 0], ["kvDraft", "Draft KV", 0],
  ["rs", "Recurrent state", 0], ["compGpu", "Compute", 1],
  ["mtpCtx", "MTP context", 0]];
var VRAM_TIPS = {}, vramAnswered = {}, vramWhy = {};
var vramVal = function (n) {
  return n >= 1024 ? (n / 1024).toFixed(1) + " GiB" : Math.round(n) + " MiB";
};
var vramWhere = function () { return "VRAM"; };
var vramDestCls = function () { return ""; };
var vramDestTip = function () { return ""; };
var state = { slots: [] };
""" + JS[_a86:_b86] + """
var m = vramModel("s1", { any: true, weightsGpu: 1024,
                          model: "Gemma-4-31B.gguf" });
var h = m.filter(function (x) { return x.k === "hdr"; })[0];
var bare = vramModel("s1", { any: true, weightsGpu: 1024 });
process.stdout.write([!!h, h ? h.lab : "",
  bare.filter(function (x) { return x.k === "hdr"; }).length].join("|"));
"""
    _rh86 = _sp40.run(["node", "-e",
                       "eval(require('fs').readFileSync(0,'utf8'))"],
                      input=_hdr86.encode(), capture_output=True, timeout=30)
    # retold p99: the model and the time are two rows now
    check(_rh86.stdout.decode().strip()
          == "true|Gemma-4-31B.gguf|0",
          "run: the report opens with the model and the launch time, and shows "
          "no header at all when the log named neither",
          _rh86.stdout.decode()[:90] + _rh86.stderr.decode()[:70])
except Exception as _eh86:
    check(False, "the patch85 header run did not RUN", str(_eh86)[:140])
nin(seg(JS, 'if (r.model || r.at)', 'if (r.exited)'), "esc(",
    "unescaped, because that label is written with textContent - escaping it "
    "would show the escapes")
try:
    # the owner's second failure, rebuilt here rather than read from a path
    # outside the tree - a gate that needs a file it did not ship cannot run
    _drf85txt = (
        "=== 2026-08-28T18:19:15 | Server 1 | slot1 ===\n"
        "0.00 I llama_model_loader: loaded meta data with 55 key-value pairs "
        "and 833 tensors from D:/m/Gemma-4-31B.gguf (version GGUF V3 (latest))\n"
        "0.01 I load_tensors:        CUDA0 model buffer size = 25604.49 MiB\n"
        "0.11 I llama_kv_cache:      CUDA0 KV buffer size =  1200.00 MiB\n"
        "0.12 I sched_reserve:      CUDA0 compute buffer size =   198.52 MiB\n"
        "0.12 I llama_prepare_model_devices: using device CUDA0 (NVIDIA "
        "GeForce RTX 5090) (0000:01:00.0) - 0 MiB free\n"
        "0.12 E llama_model_load: error loading model: invalid vector subscript\n"
        "0.12 E srv    load_model: failed to load draft model, 'D:/m/d.gguf'\n"
        "Server process exited before it became ready (exit 1)\n")
    _r85 = fp.slot_vram_report_text(_drf85txt)
    # the owner's second failure, from his own log
    _drf85 = (_r85.get("oom") and _r85.get("oomKey") == "draftGpu"
              and _r85.get("noRoom") is True
              and _r85.get("model", "").endswith(".gguf")
              and _r85.get("at", "").startswith("2026-"))
    # and the first, rebuilt from the error log beside it
    _swa85txt = (
        "=== 2026-08-28T18:18:15 | Server 1 | slot1 ===\n"
        "0.01 I load_tensors:        CUDA0 model buffer size = 25604.49 MiB\n"
        "0.11 I llama_kv_cache_iswa: creating non-SWA KV cache, size = 15360 cells\n"
        "0.11 I llama_kv_cache:      CUDA0 KV buffer size =  1200.00 MiB\n"
        "0.11 I llama_kv_cache_iswa: creating     SWA KV cache, size = 4608 cells\n"
        "0.14 E ggml_backend_cuda_buffer_type_alloc_buffer: allocating 3600.00 "
        "MiB on device 0: cudaMalloc failed: out of memory\n"
        "0.14 E llama_init_from_model: failed to initialize the context: "
        "failed to allocate buffer for kv cache\n"
        "Server process exited before it became ready (exit 1)\n")
    _s85 = fp.slot_vram_report_text(_swa85txt)
    _swaok85 = (_s85.get("oomKey") == "kvSwa" and _s85.get("oomMiB") == 3600.0
                and _s85.get("oomWhat") == "kv cache")
    # a device that re-reserves a bigger graph must not be reported as holding both
    _cp85 = fp.slot_vram_report_text(
        "0.12 I sched_reserve:      CUDA0 compute buffer size =   198.52 MiB\n"
        "0.12 I sched_reserve:  CUDA_Host compute buffer size =    40.52 MiB\n"
        "0.55 I sched_reserve:      CUDA0 compute buffer size =    64.00 MiB\n")
    _cpok85 = (abs(_cp85.get("compGpu", 0) - 262.52) < 0.01
               and abs(_cp85.get("compHost", 0) - 40.52) < 0.01)
    check(_drf85 and _swaok85 and _cpok85,
          "run: against the owner's own logs - a failed SWA cache is named as "
          "the SWA cache with its size, a drafter that met a full card is an "
          "OOM even though nothing said memory, and a re-reserved compute "
          "buffer is one MORE buffer held, not a replacement",
          str([_r85.get("oomKey"), _r85.get("noRoom"), _s85.get("oomKey"),
               _s85.get("oomMiB"), _cp85.get("compGpu")]))
except Exception as _e85x:
    check(False, "the patch85 run did not RUN", str(_e85x)[:140])

# ---------------------------------------------------------- v3.76 patch86
section("v3.76 patch86: what was asked for, and what is actually resident")
# Two servers on one card reported 30.9 + 1.76 GiB on a 31.8 GiB card. The panel
# can only report what llama.cpp announced, and llama.cpp reports what it ASKED
# for, not where it landed - so the report and the driver had to be put side by
# side before anyone could say which was wrong. Also: the patch85 header passed
# its class in the value slot and printed the word "vhdr", and a reserve line
# repeated verbatim was counted twice.
# retold p99: the time moved to its own row, so the header carries the file
check('row("hdr", r.model || r.at || "", "", "vhdr");' in JS
      and 'row("hdrAt", r.at, "", "vhdrat");' in JS,
      "the header's class goes in the class slot - patch85 put it in the value "
      "slot and the card printed it")
_vr86 = seg(py, "def slot_vram_report_text", "SLOT_LAUNCH_AT = {}")
# retold p99: without the phase. A no-vision relaunch proved the repeat was the
# drafter re-reserving, which the clip marker had been splitting into two phases.
check("_sig86 = (_k, m.group(1), m.group(2))" in _vr86
      and "if _sig86 in _seen86:" in _vr86
      and "a DIFFERENT figure is a different" in _vr86,
      "a reserve repeated with the SAME figure, device and phase is one buffer "
      "reported twice - a different figure is still a different buffer")
check("VRAM_ROW_KEYS = (" in py,
      "the rows the log sums are named once, on this side")
check("def alloc_log_record(sid, slot, rep, cfg=None):" in py
      and "def alloc_log_gpu_summary(cfg=None):" in py
      and 'os.path.join(log_dir(cfg or load_config()), "allocator.log")' in py,
      "the allocator log is its own file, and carries both records")
_ar86 = seg(py, "def alloc_log_record", "def alloc_log_gpu_summary")
check("what the engine asked for" in _ar86 and "tts_vram_probe(uuid_)" in _ar86
      and "what the driver says about this card" in _ar86,
      "the record puts what the ENGINE asked for beside what the DRIVER says is "
      "resident - the difference is the whole question")
check("is NOT in dedicated VRAM" in _ar86 and "claimed > _sum86 + 64" in _ar86,
      "and says so out loud when they disagree")
check("pinned host memory, by design, not VRAM" in _ar86,
      "with the host buffers set apart, because those are deliberate and not a "
      "fault")
_ag86 = seg(py, "def alloc_log_gpu_summary", "def tts_vram_probe")
check("panel servers here" in _ag86 and "more is in use than the card holds" in _ag86,
      "the per-card summary names the servers allocated there and flags a card "
      "holding more than it has")
_sl86 = seg(py, "def api_slot_log(body):", "def api_slot_logs")
check('if _rep86.get("ready") or _rep86.get("exited"):' in _sl86
      and "if ALLOC_LOG_DONE.get(sid) != _la86:" in _sl86,
      "written once per LAUNCH and only once it has settled - this door is "
      "polled, and a record per poll would be a log of nothing")
try:
    _d86 = _tf50.mkdtemp()
    _lg86 = os.path.join(_d86, "logs")
    os.makedirs(_lg86)
    with open(os.path.join(_lg86, "srv_slot1_2.log"), "w",
              encoding="utf-8", newline="") as _f:
        _f.write(
            "=== 2026-08-28T19:49:28 | Server 1 | slot1 ===\n"
            "0.00 I llama_model_loader: loaded meta data with 55 key-value "
            "pairs and 833 tensors from D:/m/Gemma.gguf (version GGUF V3)\n"
            "0.01 I load_tensors:        CUDA0 model buffer size = 25604.49 MiB\n"
            "0.11 I llama_kv_cache:      CUDA0 KV buffer size =  1200.00 MiB\n"
            "0.12 I sched_reserve:      CUDA0 compute buffer size =   198.52 MiB\n"
            "0.13 I sched_reserve:      CUDA0 compute buffer size =   104.50 MiB\n"
            "0.13 I sched_reserve:      CUDA0 compute buffer size =   104.50 MiB\n"
            "0.13 I srv  update_slots: all slots are idle\n")
    _cfg86 = {"settings": {"logDir": _lg86},
              "gpus": [{"id": "g1", "uuid": "GPU-a", "name": "Card A"}],
              "slots": [{"id": "slot1", "title": "Server 1", "gpuId": "g1"}]}
    _sv86 = (fp.load_config, fp.log_dir, fp.tts_vram_probe)
    try:
        fp.load_config = lambda *a, **k: _cfg86
        fp.log_dir = lambda c=None: _lg86
        fp.tts_vram_probe = lambda uuid_="": (
            26000, 32606, [("11064", "llama-server.exe", "25604")])
        fp.SLOT_LAUNCH_AT["slot1"] = 0.0
        fp.ALLOC_LOG_DONE.pop("slot1", None)
        for _i86 in range(3):
            _r86 = fp.api_slot_log({"slot": "slot1"})
        _txt86 = open(os.path.join(_lg86, "allocator.log"),
                      encoding="utf-8").read()
        _once86 = _txt86.count("| Server 1 |") == 1
        # the duplicate reserve counted once: 198.52 + 104.50, not twice over
        _comp86 = abs(_r86["report"].get("compGpu", 0) - 303.02) < 0.01
        _diff86 = "is NOT in dedicated VRAM" in _txt86
        _card86 = "panel servers here: Server 1" in _txt86
    finally:
        (fp.load_config, fp.log_dir, fp.tts_vram_probe) = _sv86
        shutil.rmtree(_d86, ignore_errors=True)
    check(_once86 and _comp86 and _diff86 and _card86,
          "run: three polls of one launch write ONE record; a reserve repeated "
          "verbatim is counted once; the record says what was asked for is not "
          "all resident; and the card summary names its servers",
          str([_once86, _comp86, _diff86, _card86]))
except Exception as _e86x:
    check(False, "the patch86 run did not RUN", str(_e86x)[:140])

# ---------------------------------------------------------- v3.76 patch87
section("v3.76 patch87: the report goes home without waiting for the network")
# The allocation report flashed once at the end of a launch and vanished, while
# the buttons on the same card came through every rebuild intact. Both are their
# own nodes, adopted from a placeholder; the difference was WHEN. ctlApply runs
# synchronously after a render, so the buttons are home before the next rebuild.
# The report was only re-adopted when a POST came back, so its node sat orphaned
