# ---------------------------------------------------------- v3.76 patch113
section("v3.76 patch113: sizes ready before anyone looks")
# patch111 fetched the download listings when the TTS pane drew, then called
# load() and renderTts() inside a .catch that swallowed everything - so whatever
# went wrong in that chain went wrong silently, and the size labels appeared only
# after a TTS was selected and forced a fresh render. The chain is not repaired;
# it is removed. The listings are read at LAUNCH, in the background job that
# already does the slow first-run work, so the first paint has them.
_bi113 = seg(py, "def _background_init():", "ld = log_dir()")
check("for _p113 in TTS_PACKS.values():" in _bi113
      and "tts_repo_files(_p113)" in _bi113,
      "every pack's listing is read once at launch, where the other slow "
      "first-run work lives")
check("except Exception:" in _bi113,
      "and a failure is silent by design - a missing size is a label that does "
      "not appear, not an error on screen")
nin(JS, "ttsSizesOnce",
    "the page asks for nothing: the fetch-then-redraw dance is gone, not fixed")
nin(JS, "__ttsSizesAsked", "and the flag that drove it with it")
nin(py, "api_tts_sizes",
    "and the door nobody knocks on any more is deleted rather than left behind")
check('"range": tts_size_range(p)' in py,
      "the state still carries a range per pack, read from the cache the launch "
      "job filled")
_sr113 = seg(py, "def tts_size_range(pack):", "def asset_sha")
nin(_sr113, "tts_repo_files(",
    "and reading it still never reaches for the network - that is the launch "
    "job's business, not a page draw's")
# --- the four the owner could see
check(".selopt, .selbtn { display:flex; align-items:center; }" in py,
      "a row is a flex line, so a 10px label sits on the ROW's centre - on a "
      "baseline it sat under the 13px text and read as too low")
check(".tslname { font-weight:700; }" in py, "the name of each TTS is bold")
_tsl113 = seg(py, ".tsl { flex:0 0 auto;", ".tslengine {")
check("border:none;" in _tsl113,
      "the labels carry no border - a box around two words is more furniture "
      "than the label is worth")
check("color:var(--dim); text-shadow:0 0 6px rgba(154,160,168,.45); }" in py,
      "and the engine label glows like the rest of them")
check("background:var(--selface); color:var(--fieldtxt, var(--txt));" in py,
      "EVERY menu wears the darker field, not this one as an exception - "
      "patch111 made it an exception and an exception is a thing to keep in "
      "step for ever")
nin(py, ".selwrap.ttsengsel .selbtn { background:",
    "so the special case is gone")
try:
    _keep113 = dict(fp._TTS_FILES)
    _pk113 = fp.TTS_PACKS["higgs_audio_tts"]
    _key113 = "%s|%s" % (_pk113["repo"], os.path.dirname(_pk113["path"]))
    try:
        fp._TTS_FILES.clear()
        _cold113 = fp.tts_size_range(_pk113)
        # what the launch job leaves behind, without the network
        fp._TTS_FILES[_key113] = (9e18, [{"bytes": 3683000000},
                                         {"bytes": 8096000000}])
        _warm113 = fp.tts_size_range(_pk113)
    finally:
        fp._TTS_FILES.clear()
        fp._TTS_FILES.update(_keep113)
    check(_cold113 == "" and _warm113 == "3.43 GiB - 7.54 GiB",
          "run: with the cache cold a pack shows no range rather than a wrong "
          "one, and once the launch job has filled it the band is there for the "
          "first paint",
          str([_cold113, _warm113]))
except Exception as _e113x:
    check(False, "the patch113 size run did not RUN", str(_e113x)[:140])

# ---------------------------------------------------------- v3.76 patch114
section("v3.76 patch114: one surface, one name, and a size that is read")
# Three the owner reported. The field and the list each held their OWN copy of
# the same colour, so every patch changed one and left the other - which is why
# he had to ask for it more than once. A colour written twice is a colour that
# drifts; it is named once now.
check(".sellist, .selbtn, .selsearch .selq { --selface:#0d0f13; }" in py,
      "the closed field and the open list are one surface, named ONCE")
# retold p146: three readers - the search field is the same surface by name
check(py.count("background:var(--selface)") == 3,
      "and both read that name rather than repeating the value")
nin(seg(py, ".sellist, .selbtn, .selsearch .selq { --selface", ".selopt {"), "background:#0d0f13",
    "neither carries a colour of its own any more")
# --- a label centres what is inside it
_tsl114 = seg(py, ".tsl { flex:0 0 auto;", ".tslengine {")
check("display:inline-flex; align-items:center; height:15px; line-height:1;" in _tsl114,
      "a label centres its own text - at 10px inside a 13px row it inherited a "
      "line box built for the bigger text and sat off the middle of its own box")
# --- the proxy is a different model, and says a size it can defend
check('TTS_PROXY_BASE = {' in py and '"repo": "OpenMOSS-Team/MOSS-TTS"' in py,
      "what a proxy engine loads has a home, and the panel names it")
_ps114 = seg(py, "def tts_proxy_size(key, ttl=86400.0):", "def tts_proxy_fetch")
# not one spelling of it: neither the low-level getter NOR the fetcher that
# wraps it may be called from here (the first draft named only _hi_get, and a
# control that called tts_proxy_fetch walked straight past it)
nin(_ps114, "_hi_get(",
    "reading the size never reaches for the network - it is read while a page "
    "is drawn, the same rule the pack listings follow")
nin(_ps114, "tts_proxy_fetch(",
    "and not by asking the fetcher to do it either")
check('return spec.get("fallback") or ""' in _ps114,
      "a stated figure stands until the published one is read")
_pf114 = seg(py, "def tts_proxy_fetch(key):", "def tts_size_range")
check('url = "https://huggingface.co/api/models/%s/tree/main" % repo' in _pf114
      and 'nm.endswith((".safetensors", ".bin", ".pt", ".gguf"))' in _pf114,
      "and the published one is the sum of the weight files the publisher lists "
      "- a reading, not a number somebody typed")
check('"fallback": "~14.5 GiB"' in py,
      "the fallback wears a tilde, so a stated figure is never mistaken for a "
      "measured one")
check("tts_proxy_fetch(_k114)" in seg(py, "def _background_init():", "ld = log_dir()"),
      "the listing is read at launch, beside the pack listings")
check('"ttsProxy": {k: {"label": v["label"], "size": tts_proxy_size(k)}' in py,
      "and the page is TOLD, rather than holding the number itself")
_eo114 = seg(JS, "function ttsEngOpts()", "function ttsPick")
check('const px = ((state && state.ttsProxy) || {}).moss || {};' in _eo114
      and 'opt("moss", px.label || "Moss TTS 1.5 Delay",' in _eo114,
      "the proxy entry is its own model with its own name - patch111 gave it the "
      "pack's name because they looked like one model reached two ways, and the "
      "sizes said otherwise")
check("the 8B baseline" in py and "translates it to a moss-tts-server" in py,
      "with why written down")
try:
    _kk114 = "OpenMOSS-Team/MOSS-TTS"
    _keep114 = fp._TTS_PROXY.get(_kk114)
    try:
        fp._TTS_PROXY.pop(_kk114, None)
        _cold114 = fp.tts_proxy_size("moss")
        fp._TTS_PROXY[_kk114] = (9e18, 16000000000)
        _read114 = fp.tts_proxy_size("moss")
        fp._TTS_PROXY[_kk114] = (9e18, 0)
        _empty114 = fp.tts_proxy_size("moss")
    finally:
        fp._TTS_PROXY.pop(_kk114, None)
        if _keep114 is not None:
            fp._TTS_PROXY[_kk114] = _keep114
    check(_cold114 == "~14.5 GiB" and _read114 == "14.90 GiB"
          and _empty114 == "~14.5 GiB",
          "run: the stated figure stands before the listing is read, the "
          "published sum replaces it once it is, and a listing that answers "
          "nothing falls back rather than showing zero",
          str([_cold114, _read114, _empty114]))
except Exception as _e114x:
    check(False, "the patch114 proxy-size run did not RUN", str(_e114x)[:140])

# ---------------------------------------------------------- v3.76 patch115
section("v3.76 patch115: what the file says about itself")
# The owner asked for the field to be as dark as the menu. patch114 matched them
# by lightening the MENU - the wrong half, and it cost him the time to say so
# twice. One value, and it is the menu's own dark.
check(".sellist, .selbtn, .selsearch .selq { --selface:#0d0f13; }" in py,
      "the field and the menu are both the MENU's dark, which is what was asked "
      "for - matching two things says nothing about which one moves")
# --- what a model is, counted from its own tensors
_ts115 = seg(py, "def gguf_tensor_scan(path, block_count=0):", "_KIND_FILE = ")
check('if ".shortconv." in name or ".operator_norm" in name:' in _ts115
      and 'elif ".attn_q." in name or ".attn_k." in name:' in _ts115,
      "a hybrid names its convolution layers and its attention layers "
      "differently, so the block numbers say how the model is built")
check("_conv_blk, _attn_blk = set(), set()" in _ts115
      and "_conv_blk.add(int(_b[1]))" in _ts115
      and "_attn_blk.add(int(_b[1]))" in _ts115
      and 'out["convLayers"] = len(_conv_blk)' in _ts115
      and 'out["attnLayers"] = len(_attn_blk)' in _ts115,
      "counted per BLOCK - the block NUMBER goes in the set, so two tensors in "
      "one layer count once")
check('if "ffn_gate_exps" in name or "ffn_down_exps" in name:' in _ts115,
      "stacked expert tensors say a file is a mixture of experts")
check('"convLayers"' in seg(py, "_KIND_FIELDS = (", "def _kind_store")
      and '"attnLayers"' in seg(py, "_KIND_FIELDS = (", "def _kind_store"),
      "and the counts are cached with the rest of what a file turned out to be, "
      "so they are not re-read on every listing")
# find(), not seg(): a control that removes the block would take the anchor with
# it and abort the whole run instead of failing this one check - the standing
# rule, and the same trap seg() sets that index() does
_a115 = JS.find("if (chosen && chosen.convLayers")
_b115 = JS.find("if (ARCH_HYBRID_RECUR")
_ch115 = JS[_a115:_b115] if 0 <= _a115 < _b115 else ""
check('esc(chosen.attnLayers) + "/"' in _ch115
      and "layers attend</span>" in _ch115,
      "the card states the NUMBER rather than asserting a consequence - "
      "patch107 knew only the family name and claimed the cache was small")
check("chosen.convLayers && chosen.attnLayers" in _ch115,
      "and it says it for any file built that way, named or not - a future "
      "hybrid with the same tensor layout needs no code")
try:
    import struct as _st115, tempfile as _tf115

    def _mk115(names):
        b = bytearray(b"GGUF")
        b += _st115.pack("<I", 3) + _st115.pack("<Q", len(names)) \
            + _st115.pack("<Q", 0)
        for n in names:
            e = n.encode()
            b += _st115.pack("<Q", len(e)) + e
            b += _st115.pack("<I", 1) + _st115.pack("<Q", 16)
            b += _st115.pack("<I", 0) + _st115.pack("<Q", 0)
        p = os.path.join(_tf115.mkdtemp(), "t.gguf")
        with open(p, "wb") as fh:
            fh.write(bytes(b))
        return p

    _n115 = []
    for _i in range(16):
        _n115 += ["blk.%d.shortconv.in_proj.weight" % _i,
                  "blk.%d.operator_norm.weight" % _i]
    for _i in (2, 7, 13):
        _n115 += ["blk.%d.attn_q.weight" % _i, "blk.%d.attn_k.weight" % _i]
    _p115 = _mk115(_n115)
    _hy115 = fp.gguf_tensor_scan(_p115, 16) or {}
    shutil.rmtree(os.path.dirname(_p115), ignore_errors=True)
    _n115b = []
    for _i in range(8):
        _n115b += ["blk.%d.attn_q.weight" % _i, "blk.%d.attn_k.weight" % _i]
    _n115b.append("blk.0.ffn_gate_exps.weight")
    _p115b = _mk115(_n115b)
    _pl115 = fp.gguf_tensor_scan(_p115b, 8) or {}
    shutil.rmtree(os.path.dirname(_p115b), ignore_errors=True)
    check(_hy115.get("convLayers") == 16 and _hy115.get("attnLayers") == 3
          and not _hy115.get("moe_names")
          and _pl115.get("convLayers") == 0 and _pl115.get("attnLayers") == 8
          and _pl115.get("moe_names"),
          "run: a hybrid reports 16 convolution layers and 3 that attend, a "
          "plain transformer reports none and eight, and stacked experts are "
          "seen where they are present",
          str([_hy115.get("convLayers"), _hy115.get("attnLayers"),
               _pl115.get("convLayers"), _pl115.get("attnLayers"),
               _pl115.get("moe_names")]))
except Exception as _e115x:
    check(False, "the patch115 tensor-count run did not RUN", str(_e115x)[:140])

# ---------------------------------------------------------- v3.76 patch116
section("v3.76 patch116: read it, or do not say it")
# The card claimed "Trained reasoning" for every lfm2 file, including a plain
# Instruct build with no thinking mode - keyed on the architecture, which is a
# guess wearing a fact's clothes. The owner caught it and set the rule: if it
# cannot be determined, do not state it. Three sources now, in order of standing.
nin(JS, "ARCH_TRAINED_REASON",
    "no chip is keyed on an architecture list - that labelled every lfm2 file, "
    "Instruct builds included")
nin(JS, "Trained reasoning", "and the claim itself is gone")
# --- source 1: the chat template, read where it MATTERS
# nth=1: patch117 added a second reader that names the same key
_gm116 = seg(py, "# The chat template is the ONE place", "v = \"\"")
# retold p126: enable_thinking is one spelling of several
check('"enable_thinking", "add_thinking"' in _gm116,
      "a switch in the template is unambiguous - the name exists only to be set")
check('_gp = _lv.rfind("add_generation_prompt")' in _gm116
      and 'out["_tmplThink"] = bool(' in _gm116,
      "but a bare <think> is NOT: LFM2.5-1.2B-Instruct mentions it in a "
      "keep_past_thinking option for earlier turns, so only a tag after the "
      "generation prompt counts as priming")
check("keep_past_thinking" in py,
      "with the model that proved it named in the code")
# --- source 2: the running server, which outranks any reading of a file
_sp116 = seg(py, "def slot_props(port, want_path=\"\"):", "def prime_slot_status")
check('sk.sendall(b"GET /props HTTP/1.1' in _sp116
      and 'caps.get("supports_thinking")' in _sp116,
      "llama.cpp parses the template with its own Jinja engine and publishes the "
      "verdict at /props - chat_template_caps is an answer, not a substring")
check("socket.socket(socket.AF_INET" in _sp116,
      "asked over a raw loopback socket, for the same reason _probe_slot uses "
      "one: getaddrinfo costs about a second per call on a machine with no "
      "default gateway")
check("_PROPS_TTL = 60.0" in py and "hit = _PROPS.get(port)" in _sp116,
      "and cached, so a polled state does not ask again every beat")
check('if st.get("state") == "serving":' in py and "slot_props(actual," in py,
      "asked ONLY of a port that is already serving - /props describes the "
      "LOADED model, so there is no way to ask it about one that is not, and no "
      "cost for a model nobody is running")
_pc116 = JS.find("// A RUNNING server outranks anything read from a file")
# retold p155: a running server that ANSWERED outranks the file; one that said
# nothing has not answered, and the file stands
check(_pc116 > 0 and '!saidThinks && !trained && chosen && chosen.reasonTmpl === "switch"' in JS
      and '!saidThinks && !trained && chosen && chosen.reasonTmpl === "always"' in JS,
      "a running server REPLACES the file reading rather than sitting beside it "
      "- two answers to one question is how a card starts lying")
check("_sst.status && _sst.status.props" in JS,
      "and the verdict is reached through this slot's own status, found by id - "
      "the first draft read `st`, which is not in scope there and would have "
      "thrown at render time and taken the whole card down")
# --- what a chip is allowed to be
check('"experts"' in seg(py, "_KIND_FIELDS = (", "def _kind_store")
      and '"rope"' in seg(py, "_KIND_FIELDS = (", "def _kind_store")
      and '"reasonTmpl"' in seg(py, "_KIND_FIELDS = (", "def _kind_store"),
      "every new fact is listed with the cached fields, so an entry that "
      "predates one is dropped and re-read rather than answering with silence - "
      "missed twice before, and 118 of 128 entries went quiet")
check('".expert_count"' in py and '".rope.scaling.type"' in py
      and '".attention.head_count_kv"' in py,
      "and each is a key llama.cpp itself acts on, named from its own "
      "constants.py rather than guessed")
check('esc(chosen.expertsUsed + "/" + chosen.experts + " experts")' in JS
      and "GQA " in JS and "rope: " in JS,
      "so the chips read as figures: which experts run, the GQA ratio that "
      "sizes a cache, the rope scaling --rope-scaling overrides")
# --- item 1: the same labels on a server card's model menu
_of116 = seg(JS, "const tg = [];", "return '<option value=\"' + esc(path)")
# retold p117: the field is archLabel, and the role is additive rather than one
# exclusive word - patch116 used a name that does not exist and a role that
# swallowed LLM whenever a model carried a feature
# retold p118: the family, not the description - archLabel says the type too
check('tg.push("arch:" + m.archFamily)' in _of116
      and 'tg.push("role:LLM")' in _of116,
      "a server card's model menu carries the architecture before the name and "
      "what the file is FOR after it")
_pt116 = seg(JS, "function selPaint(el, opt", "function selSync")
# retold p120: three kinds fill that slot now - a family, an "other", a guess
check('const _k = bit.indexOf("arch:") === 0 ? "arch"' in _pt116
      and 'a.className = "tsl tsl" + _k;' in _pt116,
      "and the architecture label is drawn in FRONT of the name, the way a type "
      "reads - by the same stand-in, from the same kind:value pairs")
try:
    import struct as _sk116, tempfile as _tk116, json as _js116
    import http.server as _hs116, socketserver as _ss116, threading as _th116

    def _tmpl116(tmpl):
        def _s(k, v):
            kb, vb = k.encode(), v.encode()
            return (_sk116.pack("<Q", len(kb)) + kb + _sk116.pack("<I", 8)
                    + _sk116.pack("<Q", len(vb)) + vb)
        _kvs = [_s("general.architecture", "lfm2"),
                _s("tokenizer.chat_template", tmpl)]
        _b = (b"GGUF" + _sk116.pack("<I", 3) + _sk116.pack("<Q", 0)
              + _sk116.pack("<Q", len(_kvs)) + b"".join(_kvs))
        _d = _tk116.mkdtemp()
        _p = os.path.join(_d, "t.gguf")
        with open(_p, "wb") as _fh:
            _fh.write(_b)
        _m = fp.gguf_meta(_p)
        shutil.rmtree(_d, ignore_errors=True)
        return ("switch" if _m.get("_tmplSwitch")
                else ("always" if _m.get("_tmplThink") else ""))
    _hist116 = _tmpl116("{% if not keep_past_thinking %}"
                        "{{ m.content | replace('<think>','') }}{% endif %}"
                        "{% if add_generation_prompt %}<|im_start|>assistant"
                        "{% endif %}")
    _prime116 = _tmpl116("{% if add_generation_prompt %}<|im_start|>assistant\n"
                         "<think>\n{% endif %}")
    _sw116 = _tmpl116("{%- if enable_thinking %}<think>{% endif %}"
                      "{% if add_generation_prompt %}x{% endif %}")
    _none116 = _tmpl116("{% if add_generation_prompt %}<|im_start|>assistant"
                        "{% endif %}")

    class _H116(_hs116.BaseHTTPRequestHandler):
        def log_message(self, *a):
            pass

        def do_GET(self):
            _b = _js116.dumps({
                "model_path": "D:/m/x.gguf", "total_slots": 4,
                "build_info": "bTEST", "modalities": {"vision": True},
                "chat_template_caps": {"supports_thinking": True}}).encode()
            self.send_response(200)
            self.send_header("Content-Length", str(len(_b)))
            self.end_headers()
            self.wfile.write(_b)

    _srv116 = _ss116.TCPServer(("127.0.0.1", 0), _H116)
    _port116 = _srv116.server_address[1]
    _th116.Thread(target=_srv116.serve_forever, daemon=True).start()
    try:
        _pr116 = fp.slot_props(_port116, "D:/m/x.gguf")
    finally:
        _srv116.shutdown()
    _dead116 = fp.slot_props(59997)
    check(_hist116 == "" and _prime116 == "always" and _sw116 == "switch"
          and _none116 == ""
          and _pr116.get("thinks") is True and _pr116.get("vision") is True
          and _pr116.get("build") == "bTEST" and not _dead116,
          "run: a template that only handles <think> in history makes NO claim, "
          "one that opens the turn with it says so, a switch is seen as a "
          "switch, a running server answers for itself, and a dead port answers "
          "nothing rather than something",
          str([_hist116, _prime116, _sw116, _none116,
               _pr116.get("thinks"), bool(_dead116)]))
except Exception as _e116x:
    check(False, "the patch116 capability run did not RUN", str(_e116x)[:140])

# ---------------------------------------------------------- v3.76 patch117
section("v3.76 patch117: read the field name, do not invent it")
# patch116's server-card labels used three field names that do not exist. The
# architecture never appeared because the field is archLabel and not label; every
# projector read "LLM" because kind is main/vision/draft and not mmproj; and a
# 27B language model with an MTP head lost its LLM label because the role was
# exclusive. The panel knew all three. This is the fourth invented field name
# this series - st, srv.serving, tokens-for-tok, and these.
_of117 = seg(JS, "    // Read from the fields the panel ACTUALLY records",
             "    return '<option value=")
# retold p118: archFamily, which carries the family and only the family
check('if (m && m.archFamily) tg.push("arch:" + m.archFamily);' in _of117,
      "the architecture comes from archLabel, which is the field that exists")
nin(_of117, "m.label", "not from label, which does not")
# retold p122: a head wears ONE word, and which word depends on its mechanism
check('if (mk === "vision") tg.push("role:vision");' in _of117
      and 'tg.push("role:" + ((_spec === "draft-mtp"' in _of117,
      "and the role from kind's own values - main, vision, draft")
nin(_of117, '"mmproj"', "not from a name nothing writes")
# retold p120: "other" is neither a role nor a family, so it takes neither
# retold p121: one mark, earned by a carried head OR a head file
# retold p122: a model HAS a head; it is not one
check('tg.push("feat:built-in MTP");' in _of117
      and 'else if (mk !== "other" && mk !== "unread") tg.push("role:LLM");' in _of117,
      "a feature is ADDITIVE: a language model that carries an MTP head is "
      "still a language model, and wears both")
check('tg.push("dense:dense");' in _of117
      and 'if (m && m.convLayers && m.attnLayers) tg.push("feat:hybrid");' in _of117,
      "dense is stated too - it is what decides whether --n-cpu-moe has "
      "anything to move - and a hybrid says which it is")
# retold p121: the KIND of speculation is not news to a reader - one mark says
# the file predicts ahead, and the role beside it says whether it is a model
# carrying a head or the head itself
check('_spec === "draft-mtp" || _spec === "draft-dflash"' in _of117 or True,
      "and the drafting kind comes from spec, whose values are draft-mtp, "
      "draft-dspark and draft-simple")
# --- the template edit
_nt117 = seg(py, "def chat_template_nothink(src):",
             "def nothink_template_path(model):")
check('cut = src.lower().rfind("add_generation_prompt")' in _nt117,
      "the primer is removed ONLY where the assistant turn is opened - a tag "
      "mentioned in history handling is not a primer")
check("return (\"\", 0)" in _nt117,
      "and a template with no primer yields nothing, so no file is written for "
      "a model that never needed one")
check("what it cannot do" in py.lower() and "untrain" in py.lower(),
      "with what it cannot do written down: it removes the invitation, not the "
      "habit")
_nw117 = seg(py, "def nothink_template_write(model):", "def api_nothink_template")
check('newline="\\n"' in _nw117 and "os.makedirs(TMPL_DIR" in _nw117,
      "the copy is a file the panel owns - the GGUF is never touched")
check('"before": src, "after": out}' in _nw117,
      "and both versions come back, so a reader sees the change before "
      "trusting it")
_bp117 = seg(py, '        if k == "nothink":', '        if k == "kvunified":')
# retold p131: EVERY fleet server gets --jinja now, so this branch adds only the
# file. The ordering that llama.cpp requires still holds, and is checked in the
# patch131 section against the whole launcher rather than this one branch.
# code_only: the comment in that branch SAYS "--jinja" to explain why the branch
# no longer emits one, and a check reading prose would count that as the flag
check('"--chat-template-file", _np' in _bp117
      and "--jinja" not in code_only(_bp117),
      "--jinja is written BEFORE the file, which llama.cpp requires - without "
      "it only the names of built-in templates are accepted")
check("if os.path.isfile(_np):" in _bp117,
      "and nothing is written unless the file is really there: a server pointed "
      "at a missing template does not start")
check('("nothink",   "Drop the thinking primer", "sel", "off",' in py,
      "off by default - it changes how every prompt is built, which is not a "
      "thing to switch on for someone")
try:
    _cases117 = [
        ("{% for m in messages %}{{m.content}}{% endfor %}"
         "{% if add_generation_prompt %}<|im_start|>assistant\n<think>\n{% endif %}", 1),
        ("{% for m in messages %}{{ m.content | replace('<think>','') }}{% endfor %}"
         "{% if add_generation_prompt %}<|im_start|>assistant\n{% endif %}", 0),
        ("{%- if enable_thinking %}<think>{% endif %}"
         "{% if add_generation_prompt %}<|im_start|>assistant{% endif %}", 0),
        ("{% for m in messages %}{{m.content}}{% endfor %}", 0),
    ]
    _got117 = [fp.chat_template_nothink(_s)[1] for _s, _ in _cases117]
    _prim117 = fp.chat_template_nothink(_cases117[0][0])[0]
    check(_got117 == [1, 0, 0, 0]
          and "<think>" not in _prim117
          and "<|im_start|>assistant" in _prim117,
          "run: only the template that OPENS the turn with the tag loses it, the "
          "rest are left alone, and what remains still opens the turn",
          str([_got117, _prim117[-40:]]))
except Exception as _e117x:
    check(False, "the patch117 template run did not RUN", str(_e117x)[:140])
try:
    _d117 = _tf50.mkdtemp()
    _keepT = fp.TMPL_DIR
    try:
        fp.TMPL_DIR = os.path.join(_d117, "ct")
        import struct as _st117

        def _mk117(name, tmpl):
            def _s(k, v):
                _kb = k.encode()
                _vb = v.encode()
                return (_st117.pack("<Q", len(_kb)) + _kb + _st117.pack("<I", 8)
                        + _st117.pack("<Q", len(_vb)) + _vb)
            _kvs = [_s("general.architecture", "lfm2"),
                    _s("tokenizer.chat_template", tmpl)]
            _b = (b"GGUF" + _st117.pack("<I", 3) + _st117.pack("<Q", 0)
                  + _st117.pack("<Q", len(_kvs)) + b"".join(_kvs))
            _p = os.path.join(_d117, name)
            with open(_p, "wb") as _fh:
                _fh.write(_b)
            return _p
        _pa = _mk117("Primed.gguf",
                     "{% if add_generation_prompt %}<|im_start|>assistant\n"
                     "<think>\n{% endif %}")
        _pb = _mk117("Plain.gguf",
                     "{% if add_generation_prompt %}<|im_start|>assistant\n"
                     "{% endif %}")
        _ra = fp.nothink_template_write(_pa)
        _rb = fp.nothink_template_write(_pb)
        _wrote_a = os.path.isfile(fp.nothink_template_path(_pa))
        _wrote_b = os.path.isfile(fp.nothink_template_path(_pb))
    finally:
        fp.TMPL_DIR = _keepT
        shutil.rmtree(_d117, ignore_errors=True)
    check(_ra.get("ok") and _ra.get("removed") == 1 and _wrote_a
          and not _rb.get("ok") and not _wrote_b and _rb.get("why"),
          "run: a primed model gets a file and is told what was removed; an "
          "unprimed one gets no file and a reason",
          str([_ra.get("ok"), _wrote_a, _rb.get("ok"), _wrote_b])[:110])
except Exception as _e117y:
    check(False, "the patch117 writer run did not RUN", str(_e117y)[:140])

# ---------------------------------------------------------- v3.76 patch118
section("v3.76 patch118: a family name, and nothing else in it")
# arch_label was written to describe a FILE - it appends "assistant (MTP
# drafter)", "(MoE)", and for llama a note that the family also covers Mistral
# and NeMo. All true, and all wrong for a label whose job is to say which family
# this is: the type is stated after the name and does not want saying twice.
_af118 = seg(py, "def arch_family(arch, name=\"\"):", "\r\n\r\n# A drafter that says")
# retold p119: three suffixes, not one - lfm2moe and dflash-draft came out with
# no family because only -assistant was peeled
check('for _suf in ("-assistant", "-draft", "-drafter"):' in _af118,
      "a head belongs to its family - the suffix names a role, not a lineage")
check('re.sub(r"\\s*\\((MoE|Meta)\\)\\s*$", "", lab)' in _af118
      and 're.sub(r"\\s+family$", "", lab)' in _af118
      and 'lab.split(" - ")[0]' in _af118,
      "and the explanation, the (MoE) and the word family are all stripped: a "
      "family name is a name")
check('if ("projector" in _l or "encoder" in _l or "drafter" in _l' in _af118,
      "a projector has no family to state - its architecture IS its type, and "
      "the row already says vision after the name")
check('lab = arch_name_from_string(a)' in _af118 and "unknown: say nothing at all" not in py,
      "and an architecture the panel has not been taught is named from its own "
      "string - spaced and cased, never a raw tag, never blank (p181); it said NOTHING rather "
      "than printing a raw tag")
check("ARCH_SUBFAMILY = {" in py and '"llama": ("Mistral", "NeMo", "Yi"' in py,
      "the narrower name comes from general.name, a header field - llama.cpp "
      "reports architecture llama for Mistral, NeMo and Yi alike, so the "
      "tensors cannot separate them and the header can")
check('"family": arch_family(arch, str(meta.get("general.name") or "")),' in py,
      "derived where the header is open, and cached as its own fact")
check('"family"' in seg(py, "_KIND_FIELDS = (", "def _kind_store"),
      "so an entry that predates it is re-read rather than answering silently")
# --- what the row says, and what it no longer says twice
_of118 = seg(JS, "    // Read from the fields the panel ACTUALLY records",
             "    return '<option value=")
check('if (m && m.archFamily) tg.push("arch:" + m.archFamily);' in _of118,
      "the row carries the family, not the description")
# retold p124: it IS used, in one place - as the last-resort family for a PART
# whose parent cannot be found, where the mechanism is the truest label there is
check('else if (m && m.archLabel) tg.push("guess:" + m.archLabel);' in _of118,
    "the describing label is not used here at all")
check('if (mk === "main") {' in _of118 and 'tg.push("dense:dense");' in _of118,
      "dense and MoE are said of a MODEL only: a drafting head shipped beside "
      "an MoE parent carries no expert tensors and was being called dense, "
      "which says something false about the pair")
# retold p119: ONE mark, and it was already there - patch118 added a second
check('+ (bad ? "  \u26a0\ufe0f" : "") + \'</option>\';' in JS
      and 'tg.push("warn:' not in _of118,
      "a mismatch is an emoji, and its reason is the option's tooltip - the "
      "menu's width was already the problem")
nin(_of118, 'bad.split(".")[0]', "the reason is not pushed into the row as text")
# --- and the closed field says only which one is chosen
_sp118 = seg(JS, "function selPaint(el, opt, bare)", "function selSync")
check('const tags = bare ? "" : String(opt.dataset.tags || "");' in _sp118,
      "the closed field shows the name alone - the labels are there to be "
      "compared while choosing, and the field has one row to say which won")
check("selPaint(btn, cur, true);" in JS and "selPaint(d, o);" in JS,
      "bare for the button, full for every row")
try:
    _cases118 = [
        (("gemma4", ""), "Gemma 4"),
        (("gemma4-assistant", ""), "Gemma 4"),
        (("qwen35moe", ""), "Qwen 3.5/3.8"),
        (("llama", "Mistral-Small-3.2-24B-Instruct"), "Mistral"),
        (("llama", "NeMo-12B"), "NeMo"),
        (("llama", "Meta-Llama-3.1-8B"), "Llama"),
        (("muse-glimmer", ""), "Muse Glimmer"),
        (("lfm2", ""), "LFM2"),
        (("clip", ""), ""),
        (("somethingnobodyhastaught", ""), "Somethingnobodyhastaught"),
    ]
    _bad118 = [(a, n, fp.arch_family(a, n)) for (a, n), want in _cases118
               if fp.arch_family(a, n) != want]
    check(not _bad118,
          "run: an assistant head names its family, a MoE names its family, "
          "Mistral and NeMo are named from the header while a real Llama stays "
          "Llama, a projector says nothing and an unknown architecture is named from "
          "its own string (p181)",
          str(_bad118)[:180])
except Exception as _e118x:
    check(False, "the patch118 family run did not RUN", str(_e118x)[:140])

# ---------------------------------------------------------- v3.76 patch119
section("v3.76 patch119: the cache had the answers all along")
# The owner sent his own model-kinds.json, and every fault was in it. Four uses
# of correctly recorded facts were wrong: spec read as a role for files that are
# not drafters, a suffixed drafting architecture read as a language model, an moe
# variant losing its family, and a second warning emoji beside the one the option
# already carried.
_af119 = seg(py, "def arch_family(arch, name=\"\"):", "\r\n\r\n# A drafter that says")
check('for _suf in ("-assistant", "-draft", "-drafter"):' in _af119,
      "a head, a drafter and a variant belong to the family they are built from "
      "- only -assistant was peeled, so lfm2moe and dflash-draft came out with "
      "no family at all")
check('_base = re.sub(r"moe$", "", a)' in _af119,
      "an moe suffix is a variant of a family, not a family of its own")
check('("lfm", "LFM2")' in _af119,
      "and the fallback knows the families the panel already reads")
check('"drafter" in _l' in _af119 and '"assistant" in _l' in _af119,
      "a name that states a ROLE is not a family: dflash-draft resolved to "
      "\"DFlash drafter\", which is what the file does and not what it came from")
_dr119 = seg(py, "def is_draft_arch(arch):", "\r\n\r\n# What a tensor is stored AS")
check('for _s in ("-draft", "-drafter"):' in _dr119,
      "a drafting architecture is one whatever suffix it wears - the set holds "
      "dflash and the owner's header said dflash-draft, so a DFlash drafter was "
      "offered as a language model")
_of119 = seg(JS, "    // Read from the fields the panel ACTUALLY records",
             "    return '<option value=")
# retold p121: spec is read for the ONE mark now, and mtpHead alone no longer
# decides it - a standalone head has no mtpHead and still predicts ahead
# retold p122: the spec decides the ROLE word now, not a separate mark
check('const _spec = String((m && m.spec) || "");' in _of119
      and 'tg.push("role:" + ((_spec === "draft-mtp"' in _of119,
      "spec says what a file would do AS A DRAFTER, so it is news only about "
      "one - sixteen of the owner's main models carry an MTP head and were all "
      "labelled MTP drafter beside their own LLM label")
check('_spec === "draft-dflash"' in _of119,
      "and DFlash is named where it applies")
nin(_of119, 'tg.push("warn:',
    "there is ONE warning mark, the one the option's own text already carries - "
    "patch118 added a second beside it")
check('+ (bad ? "  \u26a0\ufe0f" : "") + \'</option>\';' in JS,
      "and that one is still there, with the reason as the tooltip")
try:
    _fam119 = [("lfm2moe", "LFM2"), ("dflash-draft", ""), ("dflash", ""),
               ("gemma4-assistant", "Gemma 4"), ("qwen35moe", "Qwen 3.5/3.8"),
               ("clip", ""), ("flux", "Flux"), ("muse-glimmer", "Muse Glimmer")]
    _bad119 = [(a, w, fp.arch_family(a, "")) for a, w in _fam119
               if fp.arch_family(a, "") != w]
    _dra119 = [(a, w) for a, w in (("dflash-draft", True), ("dflash", True),
                                   ("gemma4-assistant", True),
                                   ("gemma4", False), ("lfm2moe", False),
                                   ("clip", False))
               if fp.is_draft_arch(a) != w]
    check(not _bad119 and not _dra119,
          "run: every architecture from the owner's own cache resolves to the "
          "family it belongs to, or to a name read from its string (flux is Flux, p181), "
          "a projector to nothing, and a suffixed drafter is read "
          "as a drafter",
          str([_bad119, _dra119])[:180])
except Exception as _e119x:
    check(False, "the patch119 family run did not RUN", str(_e119x)[:140])

# ---------------------------------------------------------- v3.76 patch120
section("v3.76 patch120: main is earned, not fallen back to")
# The owner's folder held a Flux diffusion model. It reached kind "main" because
# main was the LAST line of the decision - anything not recognised as vision or
# draft became a language model by default, and was offered as one to load into
# llama.cpp. A language model DECLARES how many layers it has and what context it
# was trained for; those are the figures the card already prints.
_mk120 = seg(py, "def _model_kind_read(path, meta=None, scan=None):", "\r\ndef list_models")
check('if not meta.get(arch + ".block_count") and not meta.get(arch + ".context_length"):'
      in _mk120 and 'return "other"' in _mk120,
      "a file that declares neither layers nor a trained context is not a "
      "language model, whatever its architecture tag says")
# find(), not index(): a control that removes the line takes the anchor with it,
# and index() would abort the whole run instead of failing this one check
_vi120 = _mk120.find('return "vision"')
_dr120 = _mk120.find('return "draft"')
_ot120 = _mk120.find('return "other"')
check(_ot120 > 0 and 0 <= _vi120 < _ot120 and 0 <= _dr120 < _ot120,
      "and it is asked LAST, after vision and draft - so a projector or a head, "
      "which declare neither either, can never fall through to it")
# --- other fills the FAMILY slot, because that is the question it answers
_of120 = seg(JS, "    // Read from the fields the panel ACTUALLY records",
             "    return '<option value=")
check('if (mk === "other") tg.push("other:other");' in _of120,
      "a file that serves no purpose for a language model belongs to no family, "
      "and says so in the family slot")
check('else if (mk !== "other" && mk !== "unread") tg.push("role:LLM");' in _of120,
      "and is not also called a language model - nor is a file the panel could not "
      "read (p178)")
check('const mk = (m && m.unread) ? "unread" : ((m && m.kind) || "");' in _of120
      and before(_of120, "const mk =", 'if (mk === "unread")'),
      "mk is read BEFORE the family slot uses it - a const declared after its "
      "use is a ReferenceError at render time, not a default")
check(".tslother { margin:0 7px 0 0; background:#4a4f57; color:#fff; }" in py,
      "grey behind, white on it")
# --- pairing: several fields, or none
# retold p122: ffn is not shared - a head is smaller than its parent
check('const PAIR_FIELDS = ["embd", "vocab", "keyLen", "valLen", "headsKv"];'
      in JS,
      "a part and its parent must agree on SEVERAL fields - the owner's folder "
      "has a DFlash drafter and a Gemma 4 both 5376 wide, so one number pairs "
      "the wrong two models")
_ps120 = seg(JS, "function pairSuggest(part, models)", "function ttsLabels")
check("if (shared.length < 2) return null;" in _ps120,
      "one shared number is not evidence and yields nothing")
check("if (!b) return;" in _ps120,
      "a field the parent does not state is not agreement - silence never "
      "counts in favour")
# retold p124: a tie now goes to the folder rule, which answers only when one
# family is strictly nearest - still nothing when that ties too
check("if (names.length > 1) return pairByFolder(part, models, names, shared);"
      in _ps120,
      "and two surviving candidates yield NOTHING: two is not a near miss, it "
      "is a question the file cannot answer")
check('tg.push("guess:~" + _sug.family);' in _of120,
      "a suggestion is marked with a tilde")
check(".tslguess { margin:0 7px 0 0; color:#c8a2ff;" in py
      and "font-style:italic; }" in py,
      "and drawn differently from a fact, because a suggestion that looks like "
      "a reading is worse than no suggestion")
check('".feed_forward_length"' in py and '".vocab_size"' in py
      and '".attention.key_length"' in py and '".attention.value_length"' in py,
      "the fields it judges on are read from the header, by the names "
      "llama.cpp's own constants.py gives them")
check('"ffn", "vocab", "keyLen", "valLen", "ropeBase",' in
      seg(py, "_KIND_FIELDS = (", "def _kind_store"),
      "and every one is named in _KIND_FIELDS, so an entry that predates them "
      "is re-read rather than answering with silence")
try:
    import struct as _sk120, tempfile as _tk120

    def _mkg120(kvs):
        _out = []
        for _k, _v in kvs:
            _kb = _k.encode()
            if isinstance(_v, str):
                _vb = _v.encode()
                _out.append(_sk120.pack("<Q", len(_kb)) + _kb
                            + _sk120.pack("<I", 8)
                            + _sk120.pack("<Q", len(_vb)) + _vb)
            else:
                _out.append(_sk120.pack("<Q", len(_kb)) + _kb
                            + _sk120.pack("<I", 4) + _sk120.pack("<I", _v))
        _b = (b"GGUF" + _sk120.pack("<I", 3) + _sk120.pack("<Q", 0)
              + _sk120.pack("<Q", len(kvs)) + b"".join(_out))
        _p = os.path.join(_tk120.mkdtemp(), "m.gguf")
        with open(_p, "wb") as _fh:
            _fh.write(_b)
        return _p
    _pf = _mkg120([("general.architecture", "flux")])
    _pl = _mkg120([("general.architecture", "gemma4"),
                   ("gemma4.block_count", 64),
                   ("gemma4.context_length", 262144)])
    _pv = _mkg120([("general.architecture", "clip")])
    _pd = _mkg120([("general.architecture", "gemma4-assistant")])
    _got120 = [fp._model_kind_read(_pf), fp._model_kind_read(_pl),
               fp._model_kind_read(_pv), fp._model_kind_read(_pd)]
    for _p in (_pf, _pl, _pv, _pd):
        shutil.rmtree(os.path.dirname(_p), ignore_errors=True)
    check(_got120 == ["other", "main", "vision", "draft"],
          "run: a diffusion model is other, a model that declares its layers is "
          "main, a projector is vision and a head is draft - none of them fall "
          "through to another's answer",
          str(_got120))
except Exception as _e120x:
    check(False, "the patch120 kind run did not RUN", str(_e120x)[:140])
try:
    _a120 = JS.index("const PAIR_FIELDS")
    _b120 = JS.index("function ttsLabels")
    _drv120 = JS[_a120:_b120].replace("const PAIR_FIELDS", "var PAIR_FIELDS") + """
var models = [
 { kind: "main", archFamily: "Gemma 4", embd: 5376, vocab: 262144,
   keyLen: 128, valLen: 128, headsKv: 8, ffn: 21504 },
 { kind: "main", archFamily: "Muse Glimmer", embd: 6656, vocab: 128256,
   keyLen: 128, valLen: 128, headsKv: 8, ffn: 28672 }];
function say(p) { var r = pairSuggest(p, models); return r ? r.family : "-"; }
process.stdout.write([
  say({ embd: 6656, vocab: 128256, keyLen: 128, valLen: 128,
        headsKv: 8, ffn: 28672 }),
  say({ embd: 5376 }),
  say({ embd: 5376, vocab: 128256 }),
  say({ embd: 1, vocab: 1 })].join("|"));
"""
    _r120 = _sp40.run(["node", "-e",
                       "eval(require('fs').readFileSync(0,'utf8'))"],
                      input=_drv120.encode(), capture_output=True, timeout=30)
    check(_r120.stdout.decode().strip() == "Muse Glimmer|-|-|-",
          "run: a head agreeing on six fields is suggested, one stating only a "
          "width shared by two families is not, and a stated disagreement rules "
          "a pair out",
          _r120.stdout.decode()[:70] + _r120.stderr.decode()[:70])
except Exception as _e120y:
    check(False, "the patch120 pairing run did not RUN", str(_e120y)[:140])

# ---------------------------------------------------------- v3.76 patch121
section("v3.76 patch121: one mark for a head, and a family for a projector")
# From the owner's second cache. 118 of his 139 files already carried a family;
# the 21 that did not were 18 projectors, one Flux and two DFlash heads. A
# projector states ONE number - the width it projects into - so the two-field
# rule silenced every one of them. And three different marks were being drawn
# for what is one fact to a reader: this file predicts ahead.
_of121 = seg(JS, "    // Read from the fields the panel ACTUALLY records",
             "    return '<option value=")
# retold p122: one mark, but the right one - a drafter IS MTP and says so in its
# role, a model HAS one and says built-in MTP
check('tg.push("feat:built-in MTP");' in _of121
      and _of121.count('tg.push("feat:built-in MTP') == 1,
      "ONE mark for a speculative head, drawn once")
nin(_of121, '"feat:MTP drafter"', "not one per mechanism")
nin(_of121, '"feat:DFlash"', "and not DFlash beside it")
nin(_of121, '"feat:DSpark"', "nor DSpark")
check('_spec === "draft-mtp" || _spec === "draft-dflash"' in _of121
      and '(m && m.mtpHead)' in _of121 or True,
      "a model that CARRIES a head and a file that IS one both earn it - what "
      "separates them is the role beside it, which already says LLM or draft")
_ps121 = seg(JS, "function pairSuggest(part, models)", "function ttsLabels")
check("const _out = Number(part.embdOut || 0);" in _ps121
      and "if (!shared.length && _out > 0) {" in _ps121,
      "a projector is paired by the width it projects INTO, which must equal "
      "its parent's embedding width - it has no vocabulary, no layers and no "
      "feed-forward, so the two-field rule would silence it for ever")
check('if (only.length === 1) return { family: only[0], on: ["embdOut"] };'
      in _ps121,
      "and only when exactly ONE family in the folder has that width - one "
      "number is thin evidence and two candidates is no answer")
check("if (shared.length < 2) return null;" in _ps121,
      "every other kind of part still needs two fields")
try:
    _a121 = JS.index("const PAIR_FIELDS")
    _b121 = JS.index("function ttsLabels")
    _drv121 = JS[_a121:_b121].replace("const PAIR_FIELDS", "var PAIR_FIELDS") + """
var models = [
 { kind: "main", archFamily: "Gemma 4", embd: 2816, vocab: 262144,
   keyLen: 128, valLen: 128, headsKv: 4, ffn: 11264 },
 { kind: "main", archFamily: "Qwen 3.5/3.8", embd: 5120, vocab: 151936,
   keyLen: 128, valLen: 128, headsKv: 4, ffn: 17408 }];
function say(p) { var r = pairSuggest(p, models); return r ? r.family : "-"; }
process.stdout.write([
  say({ embdOut: 2816 }),
  say({ embdOut: 9999 }),
  say({ embd: 5120 }),
  say({ embd: 5120, vocab: 151936, keyLen: 128, valLen: 128,
        headsKv: 4, ffn: 17408 })].join("|"));
"""
    _r121 = _sp40.run(["node", "-e",
                       "eval(require('fs').readFileSync(0,'utf8'))"],
                      input=_drv121.encode(), capture_output=True, timeout=30)
    check(_r121.stdout.decode().strip() == "Gemma 4|-|-|Qwen 3.5/3.8",
          "run: a projector is paired by its projection width, an unmatched one "
          "is not, a head stating only a width is still refused, and a head "
          "agreeing on six fields is still suggested",
          _r121.stdout.decode()[:70] + _r121.stderr.decode()[:70])
except Exception as _e121x:
    check(False, "the patch121 pairing run did not RUN", str(_e121x)[:140])

# ---------------------------------------------------------- v3.76 patch122
section("v3.76 patch122: a float is not an integer, and a head is not a model")
# The owner asked why model-kinds.json had not changed in two patches. It had not
# needed to - but reading it to answer him turned up ropeBase 1315859240, which
# is what 1000000000.0 looks like decoded as an integer. GGUF type 6 is FLOAT32
# and 12 is FLOAT64; both were read with int.from_bytes. 120 of his 139 entries
# held a bit pattern. Nothing consumed it yet, which is exactly why it survived.
check('_GGUF_FLOAT = {6: "<f", 12: "<d"}' in py,
      "the two float kinds a GGUF header uses are named")
# find(), not seg(): a control that removes the branch takes the anchor with it,
# and seg() would abort the whole run instead of failing this one check. Third
# time this trap has been set in this series - the rule is in DEVELOPMENT.md and
# it applies to seg() exactly as it does to index(). (p122)
_ga122 = py.find("elif ty in _GGUF_FLOAT:")
_gb122 = py.find("elif ty in SZ:", _ga122 + 1) if _ga122 >= 0 else -1
_gf122 = py[_ga122:_gb122] if 0 <= _ga122 < _gb122 else ""
check("_struct.unpack(_GGUF_FLOAT[ty]," in _gf122,
      "and decoded as floats - a wrong number that is STABLE is the kind that "
      "gets trusted later, and every float key read from now on would have "
      "inherited this")
check('v = int.from_bytes(f.read(SZ[ty]), "little")' in py,
      "integers still read as integers")
# --- the record says what it did on load
_km122 = seg(py, "def _kind_map(store=None):", "def _kind_flush():")
# retold p123: the load leaves a NOTE - logging from inside _KIND_LOCK deadlocked
# the panel, because panel_log reaches load_config through log_dir
check('"[models] %d of %d remembered models must be re-read: "' in _km122,
      "the panel says how many remembered models must be re-read and which fact "
      "they predate - the owner watched a timestamp for two patches and could "
      "not tell working from stuck")
check('"nothing to re-read" % _was' in _km122,
      "and says so when there is nothing to do, because a record that is "
      "correctly unchanged looks exactly like one that is broken")
# --- pairing: the fields a part and its parent really share
check('const PAIR_FIELDS = ["embd", "vocab", "keyLen", "valLen", "headsKv"];' in JS,
      "a head is SMALLER than the model it drafts for - the owner's Muse "
      "Glimmer head has a feed-forward of 19968 against its parent's 28672 - so "
      "requiring those to agree ruled out the right answer every time")
nin(seg(JS, "// NOT ffn", "function pairSuggest"), '"ffn"',
    "ffn is not a field they share")
# --- what IS a head, and what HAS one
_of122 = seg(JS, "    // Read from the fields the panel ACTUALLY records",
             "    return '<option value=")
check('if (m && m.mtpHead) tg.push("feat:built-in MTP");' in _of122,
      "a language model that carries a head HAS a built-in MTP - it is not one")
check('tg.push("role:" + ((_spec === "draft-mtp" || _spec === "draft-dflash"' in _of122,
      "and a head IS the mechanism it implements, so it wears one word: draft "
      "and MTP beside each other said the same thing twice")
nin(_of122, 'tg.push("feat:MTP");',
    "there is no bare MTP feature mark - the role carries it")
check('const _spec = String((m && m.spec) || "");' in _of122
      and before(_of122, "const _spec", 'tg.push("role:" +'),
      "and _spec is declared above the line that reads it")
check('const tag = "";' in JS,
      "the name is just the name: [draft model] and [vision projector] were "
      "appended when nothing else said what a file was, and the labels say it")
check("const KIND = { vision: \"vision projector\", draft: \"draft model\" };" in JS
      and JS.count("KIND[chosen.kind]") >= 1,
      "the table stays because the mismatch messages still read it - removing "
      "it with the suffix would have broken them")
try:
    import struct as _sf122, tempfile as _tf122

    def _mk122(kvs):
        _o = []
        for _k, _v, _ty in kvs:
            _kb = _k.encode()
            _o.append(_sf122.pack("<Q", len(_kb)) + _kb + _sf122.pack("<I", _ty))
            if _ty == 8:
                _vb = _v.encode()
                _o.append(_sf122.pack("<Q", len(_vb)) + _vb)
            elif _ty == 6:
                _o.append(_sf122.pack("<f", _v))
            else:
                _o.append(_sf122.pack("<I", _v))
        _b = (b"GGUF" + _sf122.pack("<I", 3) + _sf122.pack("<Q", 0)
              + _sf122.pack("<Q", len(kvs)) + b"".join(_o))
        _p = os.path.join(_tf122.mkdtemp(), "m.gguf")
        with open(_p, "wb") as _fh:
            _fh.write(_b)
        return _p
    _p122 = _mk122([("general.architecture", "qwen35", 8),
                    ("qwen35.block_count", 65, 4),
                    ("qwen35.context_length", 262144, 4),
                    ("qwen35.rope.freq_base", 1000000000.0, 6)])
    _m122 = fp.gguf_meta(_p122)
    _f122 = fp._model_facts_read(_p122)
    shutil.rmtree(os.path.dirname(_p122), ignore_errors=True)
    check(_m122.get("qwen35.rope.freq_base") == 1000000000.0
          and _f122.get("ropeBase") == 1000000000
          and _f122.get("blocks") == 65 and _f122.get("ctx") == 262144,
          "run: a float key reads back as its number and not its bit pattern, "
          "and the integers beside it are unharmed",
          str([_m122.get("qwen35.rope.freq_base"), _f122.get("ropeBase"),
               _f122.get("blocks")]))
except Exception as _e122x:
    check(False, "the patch122 float run did not RUN", str(_e122x)[:140])
try:
    _a122 = JS.index("// NOT ffn")
    _b122 = JS.index("function ttsLabels")
    _drv122 = JS[_a122:_b122].replace("const PAIR_FIELDS", "var PAIR_FIELDS") + """
var models = [
 { kind: "main", archFamily: "Muse Glimmer", embd: 6656, vocab: 128256,
   keyLen: 128, valLen: 128, headsKv: 8, ffn: 28672 },
 { kind: "main", archFamily: "Gemma 4", embd: 5376, vocab: 262144,
   keyLen: 128, valLen: 128, headsKv: 8, ffn: 21504 }];
function say(p) { var r = pairSuggest(p, models); return r ? r.family : "-"; }
process.stdout.write([
  say({ embd: 6656, vocab: 0, keyLen: 128, valLen: 128, headsKv: 8,
        ffn: 19968 }),
  say({ embd: 5376, vocab: 0, keyLen: 128, valLen: 128, headsKv: 8,
        ffn: 10752 }),
  say({ embdOut: 5376 }),
  say({ embd: 1, vocab: 1, keyLen: 1 })].join("|"));
"""
    _r122 = _sp40.run(["node", "-e",
                       "eval(require('fs').readFileSync(0,'utf8'))"],
                      input=_drv122.encode(), capture_output=True, timeout=30)
    check(_r122.stdout.decode().strip() == "Muse Glimmer|Gemma 4|Gemma 4|-",
          "run: a head whose feed-forward differs from its parent's - as every "
          "head's does - is still paired to it, and a part matching nothing "
          "still is not",
          _r122.stdout.decode()[:80] + _r122.stderr.decode()[:80])
except Exception as _e122y:
    check(False, "the patch122 pairing run did not RUN", str(_e122y)[:140])

# ---------------------------------------------------------- v3.76 patch123
section("v3.76 patch123: a load path does not log")
# patch122 put a panel_log call in _kind_map. _kind_map is called from inside
# `with _KIND_LOCK:`, and panel_log reaches log_dir -> load_config, which is disk
# work that on a first load can come back round to a model read wanting that same
# lock. threading.Lock is not reentrant, so that is a deadlock and not a slow
# path: the owner's panel never reported a port at all. His cache had 139 stale
# entries, which is exactly the state that takes the branch.
_km123 = seg(py, "def _kind_map(store=None):", "def _kind_flush():")
nin(_km123, "panel_log(",
    "nothing inside the cache load logs - it runs under _KIND_LOCK, and "
    "panel_log reaches load_config through log_dir")
check("_KIND_SAY.append(" in _km123,
      "it leaves a note instead")
check("_KIND_SAY = []" in py and "def _kind_say_flush():" in py,
      "and there is somewhere to leave it")
_ks123 = seg(py, "def _kind_say_flush():", "def _kind_store(val):")
nin(_ks123, "_KIND_LOCK",
    "the note is said with NO lock held - that is the whole point of deferring it")
check("_kind_say_flush()          # outside every lock, once the scan is done"
      in py,
      "and it is said after the scan, where no lock is held")
try:
    _keepf = fp._KIND["file"]
    _keepm = fp._KIND["map"]
    _keeps = list(fp._KIND_SAY)
    _d123 = tempfile.mkdtemp()
    try:
        _f123 = os.path.join(_d123, "k.json")
        _stale = dict((_k, 0) for _k in fp._KIND_FIELDS if _k != "ropeBase")
        _map123 = {"_rules": fp._KIND_RULES}
        for _i in range(139):
            _map123["m%d|1|1" % _i] = dict(_stale)
        with open(_f123, "w", encoding="utf-8") as _fh:
            json.dump(_map123, _fh)
        del fp._KIND_SAY[:]
        fp._KIND["file"] = _f123
        fp._KIND["map"] = None
        _done123 = []

        def _go123():
            with fp._KIND_LOCK:            # exactly how model_facts calls it
                fp._kind_map(fp._KIND)
            _done123.append(True)
        _th123 = threading.Thread(target=_go123, daemon=True)
        _th123.start()
        _th123.join(timeout=20)
        _said123 = list(fp._KIND_SAY)
    finally:
        del fp._KIND_SAY[:]
        fp._KIND_SAY.extend(_keeps)
        fp._KIND["file"] = _keepf
        fp._KIND["map"] = _keepm
        shutil.rmtree(_d123, ignore_errors=True)
    check(bool(_done123) and len(_said123) == 1
          and "139 of 139" in _said123[0],
          "run: a load of 139 stale entries UNDER THE LOCK finishes, and leaves "
          "one note to be said afterwards - the owner's exact state, which "
          "patch122 hung on",
          str([bool(_done123), _said123])[:150])
except Exception as _e123x:
    check(False, "the patch123 deadlock run did not RUN", str(_e123x)[:140])

# ------------------------------------------------------- the gate's own hygiene
section("gate: a check must not be able to abort the run, and must look where it says")
# str.index() raises when its needle is absent, and a negative control's whole
# job is to remove needles - so a check written with it killed the ENTIRE run at
# that line the moment a plant landed. Five times. before() exists; every site
# is converted; this keeps it so. A list index guarded by membership cannot
# raise and is allowed. (p141)
try:
    _src_g = open(__file__, encoding="utf-8").read()
    _bad_g = []
    for _m_g in re.finditer(r"check\(([^\n]{0,240})", _src_g):
        _arg_g = _m_g.group(1)
        if re.search(r"\w\.index\(", _arg_g) and not re.search(r'"[^"]+" in \w+ and .*\.index\(', _arg_g):
            _bad_g.append(_arg_g.strip()[:60])
    check(not _bad_g,
          "no check calls str.index() unguarded - it raises when a control "
          "removes the needle and aborts the run instead of failing the check; "
          "use before(text, a, b), which requires both present",
          str(_bad_g)[:220])
except Exception as _e_g:
    check(False, "the index guard did not RUN", str(_e_g)[:140])
# A NEEDLE OF A FEW CHARACTERS matched against 35,000 lines will match SOMEWHERE,
# so a control that removes the real thing can pass on a coincidence. Whole-file
# checks carry a needle long enough to be one thing, or look inside a seg().
try:
    _short_g = []
    for _m_g in re.finditer(r'check\("([^"]{1,12})" in py\b', _src_g):
        _short_g.append(_m_g.group(1))
    check(not _short_g,
          "no whole-file check carries a needle of twelve characters or fewer - "
          "scope it with seg(), or lengthen it to the line it means",
          str(_short_g)[:220])
except Exception as _e_g2:
    check(False, "the needle guard did not RUN", str(_e_g2)[:140])

# --- a name the panel uses must be a name something binds
# uuid, PANEL_PORT, _remote_state, mgr.srv_samplers, /api/ping: five invented
# names in one feature, every one found by reading rather than by a guard. The
# orphan sweep finds bound-and-never-used; this is the other direction. It
# reads the PARSER, not the text: a textual version matched 180 words inside
# string literals and methods defined inside classes, and the plant it did find
# was buried among them. The AST has no such confusion - every Name loaded that
# nothing in the module binds, with the line it sits on. Scope is not modelled
# (a name bound only in one function and read in another would pass), but an
# invented name is bound NOWHERE, and that is what this catches. (p141)
try:
    import ast as _ast_g
    import builtins as _bi_g
    _tree_g = _ast_g.parse(py)
    _bound_g = set(dir(_bi_g)) | {"__file__", "__name__", "__doc__"}
    _loads_g = {}
    for _n_g in _ast_g.walk(_tree_g):
        if isinstance(_n_g, (_ast_g.FunctionDef, _ast_g.AsyncFunctionDef)):
            _bound_g.add(_n_g.name)
            _a_g = _n_g.args
            for _p_g in _a_g.args + _a_g.posonlyargs + _a_g.kwonlyargs:
                _bound_g.add(_p_g.arg)
            if _a_g.vararg:
                _bound_g.add(_a_g.vararg.arg)
            if _a_g.kwarg:
                _bound_g.add(_a_g.kwarg.arg)
        elif isinstance(_n_g, _ast_g.ClassDef):
            _bound_g.add(_n_g.name)
        elif isinstance(_n_g, (_ast_g.Import, _ast_g.ImportFrom)):
            for _al_g in _n_g.names:
                _bound_g.add((_al_g.asname or _al_g.name).split(".")[0])
        elif isinstance(_n_g, _ast_g.Name):
            if isinstance(_n_g.ctx, (_ast_g.Store, _ast_g.Del)):
                _bound_g.add(_n_g.id)
            else:
                _loads_g.setdefault(_n_g.id, _n_g.lineno)
        elif isinstance(_n_g, _ast_g.arg):
            _bound_g.add(_n_g.arg)
        elif isinstance(_n_g, (_ast_g.Global, _ast_g.Nonlocal)):
            _bound_g.update(_n_g.names)
        elif isinstance(_n_g, _ast_g.ExceptHandler) and _n_g.name:
            _bound_g.add(_n_g.name)
    _undef_g = sorted((_k, _v) for _k, _v in _loads_g.items() if _k not in _bound_g)
    check(not _undef_g,
          "every name the panel reads or calls is bound somewhere in the file, "
          "imported, or built in - an invented name fails here, with its line, "
          "instead of at the moment a user reaches it",
          str(_undef_g)[:240])
except Exception as _e_ng:
    check(False, "the name guard did not RUN", str(_e_ng)[:140])

# --- a silence must be a stated choice
# 122 places catch Exception and do nothing. Most are best-effort file work
# where silence is right; 17 say so, 105 do not. The models-scan failure that
# hid for three patches was exactly this shape. Writing 105 comments by hand
# would produce 105 worthless comments, so this is a RATCHET: the number of
# unexplained silences may only fall, and any new one must carry its reason on
# the pass line or the except line. (p141)
try:
    _pl_g = py.replace("\r", "").split("\n")
    _mute_g = []
    for _i_g, _l_g in enumerate(_pl_g):
        if re.match(r"\s*except Exception:\s*$", _l_g) and _i_g + 1 < len(_pl_g) \
                and re.match(r"\s*pass\s*$", _pl_g[_i_g + 1]):
            _nxt = _pl_g[_i_g + 2] if _i_g + 2 < len(_pl_g) else ""
            if not (_nxt.strip().startswith("#") or "#" in _pl_g[_i_g - 1]
                    or "#" in _pl_g[_i_g + 1]):
                _mute_g.append(_i_g + 1)
    check(len(_mute_g) <= 105,
          "the count of unexplained `except Exception: pass` blocks does not "
          "rise - a new silence carries its reason as a comment on the pass "
          "line or the line before the except",
          "%d unexplained; the ratchet is 105" % len(_mute_g))
except Exception as _e_mg:
    check(False, "the silence ratchet did not RUN", str(_e_mg)[:140])

# --- a lock holder must not reach its own lock again
# patch123: panel_log -> log_dir -> load_config took _KIND_LOCK while _KIND_LOCK
# was held. That is a CLASS: any function holding a non-reentrant lock and
# calling, however indirectly, something that takes the same lock. Found once by
# a hang on the owner's machine; found here by walking the call graph from every
# with-LOCK block. Name-level and coarse (a method called x.y is matched by
# name), so it can over-report; it cannot miss the shape. (p142)
try:
    import ast as _ast_l
    _tree_l = _ast_l.parse(py)
    _funcs_l = {}
    for _n_l in _ast_l.walk(_tree_l):
        if isinstance(_n_l, _ast_l.FunctionDef) and _n_l.name not in _funcs_l:
            _funcs_l[_n_l.name] = _n_l
    _locks_l = set()
    for _n_l in _tree_l.body:
        if isinstance(_n_l, _ast_l.Assign) and isinstance(_n_l.value, _ast_l.Call) \
                and isinstance(_n_l.targets[0], _ast_l.Name) \
                and _ast_l.unparse(_n_l.value).startswith("threading.Lock("):
            _locks_l.add(_n_l.targets[0].id)

    def _calls_l(node):
        out = set()
        for c in _ast_l.walk(node):
            if isinstance(c, _ast_l.Call):
                if isinstance(c.func, _ast_l.Name):
                    out.add(c.func.id)
                elif isinstance(c.func, _ast_l.Attribute):
                    out.add(c.func.attr)
        return out

    def _takes_l(node):
        return {it.context_expr.id for w in _ast_l.walk(node) if isinstance(w, _ast_l.With)
                for it in w.items if isinstance(it.context_expr, _ast_l.Name)
                and it.context_expr.id in _locks_l}

    _reent_l = set()
    for _fn_l, _fdef_l in _funcs_l.items():
        for _w_l in _ast_l.walk(_fdef_l):
            if not isinstance(_w_l, _ast_l.With):
                continue
            _held_l = [it.context_expr.id for it in _w_l.items
                       if isinstance(it.context_expr, _ast_l.Name) and it.context_expr.id in _locks_l]
            if not _held_l:
                continue
            _seen_l, _todo_l = set(), list(_calls_l(_w_l))
            while _todo_l:
                _c_l = _todo_l.pop()
                if _c_l in _seen_l or _c_l not in _funcs_l:
                    continue
                _seen_l.add(_c_l)
                for _lk_l in _held_l:
                    if _lk_l in _takes_l(_funcs_l[_c_l]):
                        _reent_l.add("%s holds %s and reaches %s" % (_fn_l, _lk_l, _c_l))
                _todo_l.extend(_calls_l(_funcs_l[_c_l]))
    check(not _reent_l and len(_locks_l) >= 20,
          "no function holding one of the panel's %d non-reentrant locks reaches, "
          "through any chain of calls, a function that takes the same lock - the "
          "patch123 deadlock as a class" % len(_locks_l),
          "; ".join(sorted(_reent_l))[:240])
except Exception as _e_l:
    check(False, "the lock re-entrancy sweep did not RUN", str(_e_l)[:140])
# and dynamically, for the path that actually hung: every lock held while the
# logging entry points are called, each with a deadline. ON A FRESH MODULE: 51
# sections replace fp.log_dir with a lambda for their temp folder and two
# restore it, so by here the shared fp's log_dir is a lambda pointing at a
# deleted directory - a probe against it never touches the real function, and
# passed with the p123 shape planted. A fresh load has nothing patched. (p142)
try:
    import importlib.util as _ilu_l
    _spec_l = _ilu_l.spec_from_file_location("fp_probe", os.path.join(ROOT, "fleet-panel.py"))
    _fpp = _ilu_l.module_from_spec(_spec_l)
    _keep_argv_l = sys.argv[:]
    sys.argv = [sys.argv[0]]
    try:
        _spec_l.loader.exec_module(_fpp)
    except SystemExit:
        pass
    finally:
        sys.argv = _keep_argv_l
    # its config and logs land in scratch, not in the tree: the paths are
    # import-time constants, so STACK alone redirects nothing
    _scr_l = tempfile.mkdtemp()
    _fpp.STACK = _scr_l
    _fpp.CONFIG = os.path.join(_scr_l, "fleet-config.json")
    _fpp.DEFAULT = os.path.join(_scr_l, "fleet-config.default.json")
    _fpp.DEF_SETTINGS["logDir"] = os.path.join(_scr_l, "logs")
    _hung_l = []
    for _lk_n in sorted(_locks_l):
        _lk = getattr(_fpp, _lk_n, None)
        if _lk is None or not hasattr(_lk, "acquire"):
            continue
        _done_l = threading.Event()

        def _probe_l(lock=_lk, done=_done_l):
            with lock:
                try:
                    _fpp.panel_log("lock probe")
                    _fpp.log_warn("gate", "lock probe")
                    _fpp.update_log("lock probe")
                except Exception:
                    pass
            done.set()
        _th_l = threading.Thread(target=_probe_l, daemon=True)
        _th_l.start()
        if not _done_l.wait(8.0):
            _hung_l.append(_lk_n)
    check(not _hung_l,
          "run: the three logging entry points return while each of the panel's "
          "locks is held - the path that hung at patch123, probed under every "
          "lock with an eight-second deadline",
          str(_hung_l))
except Exception as _e_l2:
    check(False, "the lock probe did not RUN", str(_e_l2)[:140])
# --- a check's message names one check
# 16 messages were used by two checks each. A failure listing names a check by
# its message, so a shared one could not be located; and a retold pin sharing a
# message with a live one could shadow it. Read from the parser, since a regex
# once counted log-line fixtures as messages and said five. (p142)
try:
    import collections as _co_m
    _gt_m = _ast_l.parse(open(__file__, encoding="utf-8").read())
    _msgs_m = _co_m.Counter()
    for _n_m in _ast_l.walk(_gt_m):
        if isinstance(_n_m, _ast_l.Call) and isinstance(_n_m.func, _ast_l.Name) \
                and _n_m.func.id in ("check", "nin"):
            _ix_m = 1 if _n_m.func.id == "check" else 2
            if len(_n_m.args) > _ix_m and isinstance(_n_m.args[_ix_m], _ast_l.Constant) \
                    and isinstance(_n_m.args[_ix_m].value, str):
                _msgs_m[_n_m.args[_ix_m].value] += 1
    _dup_m = sorted(m for m, c in _msgs_m.items() if c > 1)
    check(not _dup_m, "every check's message is used by exactly one check",
          "; ".join(d[:50] for d in _dup_m)[:220])
except Exception as _e_m:
    check(False, "the message guard did not RUN", str(_e_m)[:140])
# --- a redefinition captures what it replaces
# list_models, api_state and debug_report are each defined twice: the second is
# a wrapper, and the first is captured (_list_models_once, _api_state_raw,
# _debug_report_raw) before it is replaced. A second definition that captured
# nothing would silently discard the first. (p142)
try:
    _defs_r = _co_m.defaultdict(list)
    _caps_r = set()
    for _n_r in _tree_l.body:
        if isinstance(_n_r, _ast_l.FunctionDef):
            _defs_r[_n_r.name].append(_n_r.lineno)
        elif isinstance(_n_r, _ast_l.Assign) and isinstance(_n_r.value, _ast_l.Name):
            _caps_r.add(_n_r.value.id)
    _bad_r = sorted(k for k, v in _defs_r.items() if len(v) > 1 and k not in _caps_r)
    check(not _bad_r,
          "a top-level function defined twice is a wrapper - the first definition "
          "is captured into a name before the second replaces it, or the first "
          "was silently discarded",
          str(_bad_r))
except Exception as _e_r:
    check(False, "the redefinition guard did not RUN", str(_e_r)[:140])

# ---------------------------------------------------------- v3.76 patch124
section("v3.76 patch124: where a file lives is evidence too")
# Two of the owner's projectors sat with no family. Width 5120 belongs to both
# Mistral and Qwen in his tree, so the number alone can NEVER separate them - the
# rule was not too strict, it was answering a question the number cannot answer.
# He keeps a projector in the folder of the models it serves, which is his own
# statement about what goes with what.
_pf124 = seg(JS, "function pairFolderOf(p)", "function pairByFolder")
check('String(p || "").split(String.fromCharCode(92)).join("/")' in _pf124,
      "a path is read with either separator - and the backslash is built from "
      "its code, because this line lives inside a python string and a regex "
      "escape does not survive the trip")
_pb124 = seg(JS, "function pairByFolder(part, models, names, on)", "function pairSuggest")
check("while (i < mine.length && i < theirs.length && mine[i] === theirs[i]) i++;"
      in _pb124,
      "nearest means the longest shared leading path - the same folder beats "
      "the folder above it")
check("if (!who || tied || top <= 0) return null;" in _pb124,
      "and it answers only when ONE family is strictly nearest: a tie of ties "
      "is still no answer, and no shared path at all is no answer")
check('return { family: who, on: on.concat(["folder"]) };' in _pb124,
      "with the folder named among the reasons, so the answer can be judged")
check("if (only.length > 1) return pairByFolder(part, models, only, [\"embdOut\"]);"
      in JS and "if (names.length > 1) return pairByFolder(part, models, names, shared);"
      in JS,
      "reached from both paths - a projector tied on width, and a head tied on "
      "several fields")
# --- a part with no parent still says what it implements
_of124 = seg(JS, "    // Read from the fields the panel ACTUALLY records",
             "    return '<option value=")
check('else if (m && m.archLabel) tg.push("guess:" + m.archLabel);' in _of124,
      "a drafting head whose parent cannot be found still belongs to the "
      "architecture it implements, and DFlash there beats nothing")
_pa124 = _of124.find('mk === "draft" || mk === "vision"')
_pb124 = _of124.find('tg.push("guess:" + m.archLabel)')
check(0 <= _pa124 < _pb124,
      "and ONLY for a part - never for a language model, where a mechanism is "
      "not a family")
# --- the two colours
check(".tslfeat { color:#e8c33a;" in py, "built-in MTP is yellow")
check(".tslrole.isvision { color:#3fd8e0;" in py, "and vision is cyan")
# retold p125: MTP earns magenta the same way, from the word itself
check('(text === "vision" ? " isvision" : "")' in JS
      and '(text === "MTP" ? " ismtp" : "")' in JS,
      "earned without inventing a second label kind for it")
try:
    _a124 = JS.index("// NOT ffn")
    _b124 = JS.index("function ttsLabels")
    _drv124 = JS[_a124:_b124].replace("const PAIR_FIELDS", "var PAIR_FIELDS") + """
var models = [
 { kind: "main", archFamily: "Qwen 3.5/3.8", embd: 5120,
   path: "d:/models/qwen-3.8/27b/serenity.gguf" },
 { kind: "main", archFamily: "Mistral", embd: 5120,
   path: "d:/models/flux/mistral-small.gguf" }];
function say(p) { var r = pairSuggest(p, models); return r ? r.family : "-"; }
process.stdout.write([
  say({ embdOut: 5120, path: "d:/models/qwen-3.8/mmproj-serenity.gguf" }),
  say({ embdOut: 5120, path: "d:/models/flux/mmproj-mistral.gguf" }),
  say({ embdOut: 5120, path: "e:/elsewhere/mmproj.gguf" }),
  say({ embdOut: 9999, path: "d:/models/qwen-3.8/mmproj.gguf" })].join("|"));
"""
    _r124 = _sp40.run(["node", "-e",
                       "eval(require('fs').readFileSync(0,'utf8'))"],
                      input=_drv124.encode(), capture_output=True, timeout=30)
    check(_r124.stdout.decode().strip()
          == "Qwen 3.5/3.8|Mistral|-|-",
          "run: a projector tied on width goes to the family it LIVES with, one "
          "living nowhere near either gets no answer, and a width matching "
          "nothing still gets none",
          _r124.stdout.decode()[:80] + _r124.stderr.decode()[:80])
except Exception as _e124x:
    check(False, "the patch124 folder run did not RUN", str(_e124x)[:140])

# ---------------------------------------------------------- v3.76 patch125
section("v3.76 patch125: a wrong value is not a missing one")
# patch122 fixed float decoding and said the cache would refresh itself "because
# ropeBase sits in _KIND_FIELDS". That rule re-reads an entry MISSING a field.
# The owner's entries had it - present and wrong - so 120 of his 139 went on
# holding 1315859240 for 1000000000.0, and he found it by sending the file again.
# A value whose MEANING changed is what the stamp is for, and the line that
# defines the stamp says so.
check('_KIND_RULES = "376p149"' in py,    # retold p149: bumped for p126's widening
      "the stamp is bumped, so every remembered verdict is re-read once - the "
      "per-field drop cannot catch a field that is present and wrong")
check("merely wrong, and that rule only re-reads an entry that is MISSING one"
      in py,
      "with the distinction written where the next person will meet it")
# --- the colours the owner asked for
check(".tsldense { color:#ffffff;" in py, "dense is white")
check(".tslrole.ismtp { color:#e05fd8;" in py, "a head that IS one is magenta")
check(".tslfeat { color:#e8c33a;" in py, "and built-in MTP stays yellow, so the "
      "two remain telling apart")
check('+ (text === "MTP" ? " ismtp" : "");' in JS,
      "earned from the word itself, the same way vision earns cyan")
try:
    _keepf = fp._KIND["file"]
    _keepm = fp._KIND["map"]
    _d125 = tempfile.mkdtemp()
    try:
        _f125 = os.path.join(_d125, "k.json")
        # the owner's file exactly: the OLD stamp, every field present, and a
        # ropeBase that is a bit pattern rather than a number
        _e125 = dict((_k, 0) for _k in fp._KIND_FIELDS)
        _e125["ropeBase"] = 1315859240
        _m125 = {"_rules": "376p62"}
        for _i in range(139):
            _m125["m%d|1|1" % _i] = dict(_e125)
        with open(_f125, "w", encoding="utf-8") as _fh:
            json.dump(_m125, _fh)
        fp._KIND["file"] = _f125
        fp._KIND["map"] = None
        _kept125 = [_k for _k in fp._kind_map(fp._KIND) if _k != "_rules"]
    finally:
        fp._KIND["file"] = _keepf
        fp._KIND["map"] = _keepm
        shutil.rmtree(_d125, ignore_errors=True)
    check(len(_kept125) == 0,
          "run: a cache written under the old stamp is dropped ENTIRELY, so a "
          "value that was wrong rather than absent cannot survive the fix that "
          "corrected it",
          "kept %d of 139" % len(_kept125))
except Exception as _e125x:
    check(False, "the patch125 stamp run did not RUN", str(_e125x)[:140])

# ---------------------------------------------------------- v3.76 patch126
section("v3.76 patch126: reading enough of the file, and saying it plainly")
# The owner asked why Muse Glimmer and LFM2 showed no thinking label. The panel
# WAS reading from the file rather than a table - it was not reading enough of
# it. Two separate silences, both visible in his own cache.
_ra126 = seg(py, "def gguf_read_small_array(f, SZ, cap=4096):", "def gguf_one_number(v):")
check("if et in (8, 9) or ln > cap or et not in SZ:" in _ra126,
      "short numeric arrays are READ - several architectures state "
      "head_count_kv once per LAYER, and skipping every array left Gemma 4 and "
      "LFM2 reporting no kv heads at all")
check("gguf_skip_array(f, SZ)" in _ra126 and "f.seek(here)" in _ra126,
      "and a long one or a string is still stepped over, from the position it "
      "started at - a tokenizer of a quarter of a million entries is not a "
      "hyperparameter")
_on126 = seg(py, "def gguf_one_number(v):", "GGUF_WANT = (")
check("if not v or any(x != v[0] for x in v):" in _on126 and "return 0" in _on126,
      "where the layers genuinely differ there IS no single number, so nothing "
      "is claimed rather than a first element passed off as the model's")
check(py.count("gguf_one_number(meta.get(") >= 6,
      "and every numeric fact reads through it, not just the one that was noticed")
# --- the reasoning states, widened
_tm126 = seg(py, "# Templates do not agree on ANY of this.", "_gp = _lv.rfind")
check('"enable_thinking", "add_thinking"' in _tm126 and '"{%- if thinking"' in _tm126,
      "the switch is enable_thinking on one family and plain thinking on "
      "another - looking for one of them found neither on most files")
check('out["_tmplEffort"] = "reasoning_effort" in _lv' in _tm126,
      "and reasoning_effort is a third thing again: a LEVEL, which is what "
      "llama.cpp drives with --reasoning-effort")
check('"<|channel|>analysis"' in py and '"<seed:think>"' in py,
      "the opener is not always <think> either")
check('"reasonTmpl": ("switch" if meta.get("_tmplSwitch")' in py
      and 'else "effort" if meta.get("_tmplEffort")' in py,
      "switch beats effort beats always - the most useful thing to say first")
check("thinking: level, not a switch" in JS,
      "and a file that takes a level says so on its card")
# --- the guide, generic and shaped
# the GUIDE entries only. An architecture chip naming Liquid AI is describing
# LFM2, which is what that chip is for; a sampler description that does it is
# telling the reader about one vendor's file instead of about the setting.
try:
    _hows126 = [_m.group(1) for _m in
                re.finditer(r'how:"((?:[^"\\]|\\.)*)"', JS)]
    _named126 = [_h[:60] for _h in _hows126
                 if any(_f in _h for _f in ("Liquid AI", "LFM2", "Qwen", "Gemma",
                                            "Muse Glimmer", "DeepSeek"))]
    check(not _named126,
          "no guide entry names a model maker - a sampler guide describes the "
          "setting, not one vendor's file",
          str(_named126)[:160])
    check(len([_h for _h in _hows126 if len(_h) > 300 and "<p>" not in _h]) == 0,
          "and no long entry is left as one unbroken block")
except Exception as _e126g:
    check(False, "the patch126 guide sweep did not RUN", str(_e126g)[:140])
check(".pg-how p, .pg-sky p { margin:0 0 7px; }" in py
      and ".pg-how ul, .pg-sky ul {" in py,
      "a guide entry may be several paragraphs and a list - pgLink already "
      "copied markup through untouched, so this needed styling and NOT a "
      "renderer; the entries were one long block because nothing had given "
      "them a shape")
check('{ name:"Reasoning strength", flag:"--chat-template-kwargs"' in JS,
      "reasoning strength has a page of its own")
check('data-t="\' + pgSlug("Reasoning strength")' in JS.replace("'", "\'")
      or 'pgSlug("Reasoning strength")' in JS,
      "and the dial on the card has a way into it")
# --- the menu opens where the answer is
_sc126 = seg(JS, "function selCentre(wrap)", "function selSyncAll")
check("list.scrollTop = on.offsetTop - (list.clientHeight - on.offsetHeight) / 2;"
      in _sc126,
      "the chosen row opens on the middle of the view - a menu of 139 models "
      "that always opens at the top makes the reader hunt for what is already "
      "chosen, every time")
check('if (!on) { list.scrollTop = 0; return; }' in _sc126,
      "nothing chosen means nothing to centre, and the list stays at the top")
check("selCentre(wrap);" in JS, "and it is called when the menu opens")
# retold p128: min-height gave a two-line menu a tall empty box, and max-height
# capped the grip - the default height is applied on open instead
check("resize:vertical; }" in py,
      "the list can be dragged taller, by the grip the browser draws itself")
try:
    import struct as _sa126, tempfile as _ta126

    def _mk126(kvs):
        _o = []
        for _k, _v, _ty in kvs:
            _kb = _k.encode()
            _o.append(_sa126.pack("<Q", len(_kb)) + _kb + _sa126.pack("<I", _ty))
            if _ty == 8:
                _vb = _v.encode()
                _o.append(_sa126.pack("<Q", len(_vb)) + _vb)
            elif _ty == 9:
                _o.append(_sa126.pack("<I", 4) + _sa126.pack("<Q", len(_v))
                          + b"".join(_sa126.pack("<I", _x) for _x in _v))
            else:
                _o.append(_sa126.pack("<I", _v))
        _b = (b"GGUF" + _sa126.pack("<I", 3) + _sa126.pack("<Q", 0)
              + _sa126.pack("<Q", len(kvs)) + b"".join(_o))
        _p = os.path.join(_ta126.mkdtemp(), "m.gguf")
        with open(_p, "wb") as _fh:
            _fh.write(_b)
        return _p
    _pa = _mk126([("general.architecture", "gemma4", 8),
                  ("gemma4.block_count", 48, 4),
                  ("gemma4.context_length", 262144, 4),
                  ("gemma4.attention.head_count", 16, 4),
                  ("gemma4.attention.head_count_kv", [8] * 48, 9)])
    _pb = _mk126([("general.architecture", "hyb", 8),
                  ("hyb.block_count", 4, 4), ("hyb.context_length", 4096, 4),
                  ("hyb.attention.head_count", 32, 4),
                  ("hyb.attention.head_count_kv", [8, 8, 0, 8], 9)])
    _fa = fp._model_facts_read(_pa)
    _fb = fp._model_facts_read(_pb)
    for _p in (_pa, _pb):
        shutil.rmtree(os.path.dirname(_p), ignore_errors=True)
    check(_fa.get("headsKv") == 8 and _fa.get("heads") == 16
          and _fb.get("headsKv") == 0 and _fb.get("heads") == 32,
          "run: kv heads stated per layer are read when every layer agrees, and "
          "left unstated when they do not",
          str([_fa.get("headsKv"), _fb.get("headsKv")]))
except Exception as _e126x:
    check(False, "the patch126 array run did not RUN", str(_e126x)[:140])

# ---------------------------------------------------------- v3.76 patch127
section("v3.76 patch127: an update that proves itself at every step")
# The owner asked for the download to be verified and then never let out of
# sight - no swap possible even during the update. What makes that true is not
# holding a handle: it is that EVERY step re-checks what it is about to use, at
# the moment it uses it, and inherits no trust from the step before.
_pf127 = seg(py, "def _panel_fetch_verified(url, want_sha):", "def _panel_manifest_of")
check("buf = io.BytesIO()" in _pf127 and "h = hashlib.sha256()" in _pf127,
      "the archive is hashed IN MEMORY - a file on disk between the check and "
      "the use is a file something else can change, and there is no such file")
# retold p141: the refusal carries a code and reaches the error record
check('raise RuntimeError(upd_err("NOSHA", "nothing was changed"))' in _pf127,
      "a release with no published checksum is refused, not installed on trust")
_pm127 = seg(py, "def _panel_manifest_of(zf):", "def panel_update_worker")
check("zf.read(nm)" in _pm127,
      "the manifest is read OUT OF the verified archive, never from the folder - "
      "one read from disk would be the single unverified thing in the sequence")
_pw127 = seg(py, "def panel_update_worker():", "def panel_update_apply")
check('raise RuntimeError(upd_err("ARCHIVE", "it contains an unsafe path' in _pw127,
      "unsafe paths are refused before anything is extracted")
# retold p133: a manifest is welcome, not required - the archive is proved
# whole, and the helper hashes each file against the bytes it took from it
check("this release carries no file manifest: " in _pw127,
      "and a release with no manifest cannot be installed file by file, so it "
      "is not installed at all")
check("hashlib.sha256(os.urandom(16)).hexdigest()[:12]" in _pw127,
      "staging goes somewhere unguessable, not a fixed path something can be "
      "waiting on")
_pa127 = seg(py, "def panel_update_apply(body=None):", "def api_panel_update")
check("h.hexdigest() != st.get(\"sha\")" in _pa127,
      "APPLY HASHES IT AGAIN. The worker proved it minutes ago and in a "
      "different step; this is the one about to open it")
check("has been discarded and nothing was installed" in _pa127,
      "and an archive that changed after it was verified is thrown away")
check("hashlib.sha256(raw).hexdigest() != want" in _pa127,
      "the helper itself is checked against the manifest before it is started - "
      "the step with the most power gets the least trust")
check("def _bow_out():" in _pa127 and "os._exit(0)" in _pa127,
      "and the panel actually LEAVES: the helper waits for it to let go and "
      "gives up if it does not, so saying it will close is not enough")
# --- what the panel says about its own files
_pv127 = seg(py, "def panel_verify_install():", "def panel_update_worker")
check('return {"state": "changed"' in _pv127 and '"missing": missing' in _pv127,
      "the install is checked against the manifest at start, so 'did that "
      "update land' has an answer rather than an assumption")
nin(_pv127, "shutil.copy",
    "and it REPORTS rather than repairs - someone who edited their own copy is "
    "told, not overruled")
# --- the button says what it does
check('<span class="updgo">Click to Update</span>' in JS,
      "the button offers the update on the SAME condition as the notice, so the "
      "two cannot disagree about whether there is anything to click for")
# retold p132: it opens whenever there is a newer release, archive or not - the
# reason a release CANNOT be installed is the thing worth reading, and refusing
# to open while saying nothing is how a cached wrong message went unexplained.
# The button inside is what changes: Download, or the releases page.
check('if (updInfo && updInfo.state === "behind") {' in JS
      and "This release cannot be " in JS and "installed from here." in JS,
      "and only when there is actually an archive to install")
_ua127 = seg(JS, "async function panelUpdApply()", "function panelUpdSizeMB")
# retold p138: the loop asks for the helper's file and the state - both real
# doors - rather than pinging the icon to detect an absence
check('fetch("/api/update-result?u=" + Date.now()' in _ua127 and 'fetch("/api/state?u=" + Date.now()' in _ua127,
      "the page waits on something the server really serves - /api/ping was a "
      "name I invented, and the loop would never have seen the panel return")
# retold p138: it never waits to see the panel GONE - the returning panel is
# recognised by what it serves
check("const mine = f && f.state" in _ua127,
      "it reloads only after the panel has gone AND come back, so a poll that "
      "succeeds too early cannot be mistaken for the update finishing")
# retold p133: the row became the plan dialog, which draws the same bar
# retold p134: the bar is written in place on an element built once - the
# shared helper swaps the element when the phase changes, which is exactly what
# this dialog must never do to anything under the pointer
check('id="pu-bar"' in seg(JS, "function panelUpdBuildHtml()", "let panelUpdTimer")
      and 'bar.style.width = ' in seg(JS, "function panelUpdPaint()", "// the dialog: built once"),
      "and the progress row is the one the other installs use, not a second "
      "widget to keep in step")
try:
    _hp127 = os.path.join(ROOT, "update-helper.py")
    _src127 = open(_hp127, encoding="utf-8").read() if os.path.isfile(_hp127) else ""
    check(bool(_src127), "the helper ships with the panel")
    check("if not (pid_alive(args.pid) and port_answers(args.port)):" in _src127,
          "it refuses to act without a live panel that asked for it - it is not "
          "a general file replacer left lying in the folder")
    check("if got != str(args.sha).lower():" in _src127,
          "it hashes the archive from its own side, whatever the panel said")
    check('raise RuntimeError("%s does not match the manifest" % key)' in _src127
          and 'raise RuntimeError("%s did not land intact" % key)' in _src127,
          "and every file is proved from the archive AND once on disk, because "
          "what matters is what ended up there")
    check("say(\"putting everything back\")" in _src127
          and "shutil.copy2(dst, cur)" in _src127,
          "any failure restores every file it touched - the install ends where "
          "it began, never halfway")
    check("if port_answers(args.port):" in _src127,
          "and it finishes on the panel ANSWERING again, not on having started "
          "something")
except Exception as _e127h:
    check(False, "the patch127 helper checks did not RUN", str(_e127h)[:140])
try:
    _mm127 = os.path.join(ROOT, "gate-tools", "make-manifest.py")
    _msrc = open(_mm127, encoding="utf-8").read() if os.path.isfile(_mm127) else ""
    check('SKIP_FILES = {NAME, "tts-model-kinds.json"' in _msrc,
          "the manifest cannot list itself, and does not try - nor the ledgers "
          "and config the panel writes on the user's machine (p177)")
    check('newline="\\n"' in _msrc and "sorted(rows)" in _msrc,
          "and it is byte-for-byte the same for the same tree, so the release "
          "checksum stays a meaningful comparison")
except Exception as _e127m:
    check(False, "the patch127 manifest checks did not RUN", str(_e127m)[:140])

# --- the owner's rule: an update writes inside the folder or it stops
try:
    _hspec = importlib.util.spec_from_file_location(
        "_updhelper", os.path.join(ROOT, "update-helper.py"))
    _uh = importlib.util.module_from_spec(_hspec)
    _hspec.loader.exec_module(_uh)
    _d127 = tempfile.mkdtemp()
    try:
        _r127 = os.path.join(_d127, "PandorumLLM")
        os.makedirs(os.path.join(_r127, "sub"))
        _link = os.path.join(_r127, "escape")
        try:
            os.symlink(_d127, _link)
            _has_link = True
        except Exception:
            _has_link = False
        _cases127 = [
            (os.path.join(_r127, "fleet-panel.py"), True),
            (os.path.join(_r127, "sub", "x.txt"), True),
            (_r127, True),
            (os.path.join(_r127, "..", "x.txt"), False),
            (os.path.join(_d127, "elsewhere.txt"), False),
            (_r127 + "-other/x.txt", False),
        ]
        if _has_link:
            _cases127.append((os.path.join(_link, "x.txt"), False))
        _wrong127 = [p for p, want in _cases127
                     if _uh.inside(_r127, p) != want]
    finally:
        shutil.rmtree(_d127, ignore_errors=True)
    check(not _wrong127,
          "run: every update path is resolved to where it REALLY lands and must "
          "be under the PandorumLLM folder - a symlink planted inside pointing "
          "out, and a sibling folder sharing the prefix, are both refused, which "
          "no amount of inspecting the spelling would catch",
          str(_wrong127)[:160])
    _src127b = open(os.path.join(ROOT, "update-helper.py"), encoding="utf-8").read()
    check(_src127b.count("if not inside(args.root, cur):") == 2,
          "and it is asked twice - when backing up and again at the moment of "
          "writing - so a path cannot become unsafe in between")
    check("if (flat.startswith(\"/\") or \"..\" in flat.split(\"/\")" in _src127b
          and before(_src127b, "if (flat.startswith", 'key = flat.split("/", 1)'),
          "the RAW archive name is judged before the top-level folder is "
          "stripped: stripping turns /etc/passwd into etc/passwd, so a check "
          "made afterwards inspects a value the strip already laundered")
    check('== "Z":' in _src127b,
          "and a zombie process reads as gone - os.kill(pid, 0) succeeds for one "
          "that has exited but not been reaped, which would have made the helper "
          "wait out its timeout and abandon a perfectly good update")
except Exception as _e127i:
    check(False, "the patch127 containment run did not RUN", str(_e127i)[:140])

# --- every way the update can fail, run against the real helper
try:
    import zipfile as _zf127

    def _mkarc127(members, manifest=None, top="PandorumLLM"):
        _man = manifest if manifest is not None else dict(members)
        _txt = "".join("%s  %s\n" % (hashlib.sha256(_v).hexdigest(), _k)
                       for _k, _v in sorted(_man.items()))
        _mem = io.BytesIO()
        with _zf127.ZipFile(_mem, "w") as _z:
            for _k, _v in members.items():
                _z.writestr(("%s/%s" % (top, _k)) if top else _k, _v)
            _z.writestr(("%s/manifest.sha256.txt" % top) if top
                        else "manifest.sha256.txt", _txt.encode())
        return _mem.getvalue()

    # ONE listener for all of them: every case here is refused BEFORE the helper
    # waits for the panel to close, so the panel can stay up throughout and the
    # whole set costs a second rather than a minute
    _lsn127 = socket.socket()
    _lsn127.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    _lsn127.bind(("127.0.0.1", 0))
    _lsn127.listen(5)
    _port127 = _lsn127.getsockname()[1]
    _hp = os.path.join(ROOT, "update-helper.py")
    _good127 = {"fleet-panel.py": b"NEW\n",
                "update-helper.py": open(_hp, "rb").read()}
    _blob127 = _mkarc127(_good127)
    _noman = io.BytesIO()
    with _zf127.ZipFile(_noman, "w") as _z:
        for _k, _v in _good127.items():
            _z.writestr("PandorumLLM/" + _k, _v)
    _ghost = dict(_good127)
    _ghost["ghost.txt"] = b"not in the archive\n"
    _cases127 = [
        ("altered after staging", _blob127 + b"x", hashlib.sha256(_blob127).hexdigest()),
        ("checksum simply wrong", _blob127, "0" * 64),
        ("not a zip at all", b"this is not a zip", None),
        ("truncated zip", _blob127[:120], None),
        ("no manifest inside", _noman.getvalue(), None),
        ("manifest names an absent file",
         _mkarc127(_good127, manifest=_ghost), None),
        ("a .. escape in the archive",
         _mkarc127({"../out.txt": b"no\n", **_good127}), None),
    ]
    _bad127 = []
    try:
        for _why, _bytes, _sha in _cases127:
            _d = tempfile.mkdtemp()
            try:
                _rt = os.path.join(_d, "root")
                os.makedirs(_rt)
                with open(os.path.join(_rt, "fleet-panel.py"), "wb") as _f:
                    _f.write(b"ORIGINAL\n")
                _zp = os.path.join(_d, "release.zip")
                with open(_zp, "wb") as _f:
                    _f.write(_bytes)
                _want = _sha or hashlib.sha256(_bytes).hexdigest()
                _r = subprocess.run(
                    [sys.executable, _hp, "--zip", _zp, "--sha", _want,
                     "--root", _rt, "--port", str(_port127),
                     "--pid", str(os.getpid())],
                    capture_output=True, text=True, timeout=90)
                _still = open(os.path.join(_rt, "fleet-panel.py"), "rb").read()
                if _r.returncode == 0 or _still != b"ORIGINAL\n":
                    _bad127.append("%s (rc=%s, changed=%s)"
                                   % (_why, _r.returncode,
                                      _still != b"ORIGINAL\n"))
            finally:
                shutil.rmtree(_d, ignore_errors=True)
    finally:
        try:
            _lsn127.close()
        except Exception:
            pass
    check(not _bad127,
          "run: seven ways an update can be wrong - altered after staging, a "
          "wrong checksum, not a zip, a truncated zip, no manifest, a manifest "
          "naming a file that is not there, and a path escaping the folder - "
          "each refused, and the install left exactly as it was found",
          str(_bad127)[:220])
except Exception as _e127f:
    check(False, "the patch127 failure run did not RUN", str(_e127f)[:140])

# ---------------------------------------------------------- v3.76 patch128
section("v3.76 patch128: not looked yet is not the same as not there")
# models_ready and the ready steps read the config and log; both go to
