# retold p148: the field is the menu's now - the prompt dims rather than
# vanishes on focus, and the glass is a white STROKE, not a fill colour
check(".selsearch .selq::placeholder" in py and ".selsearch .selq:focus::placeholder { opacity:.45; }" in py
      and ".selsearch .selmag" in py and "stroke:#fff;" in seg(py, ".selsearch .selmag", ".selopt {"),
      "the prompt is dimmed with a faint white halo and leaves on focus; the "
      "glass is white with a still accent halo")
# retold p148: the field is the menu's - it wears the menu's black glow, not
# the bar's accent glow on hover
check("box-shadow:0 -10px 26px -6px rgba(0,0,0,.92), 0 0 16px -2px rgba(0,0,0,.85); }" in seg(py, "  .selsearch .selq {", ".selsearch .selq::placeholder"),
      "and the field wears the menu's glow, as the bar-glow it had at p146 was wrong")
try:
    if JSDOM_CWD is None:
        raise RuntimeError("jsdom is not installed and could not be fetched - this run is skipped")
    _a146 = JS.index("function enhanceSelects(root)")
    _b146 = JS.index("function tipHarvest()")
    _sf146 = os.path.join(tempfile.mkdtemp(), "sel.js")
    with open(_sf146, "w", encoding="utf-8", errors="surrogatepass") as _f:
        _f.write(JS[_a146:_b146])
    _drv146 = """
const {JSDOM} = require(%r);
const fs = require("fs");
const dom = new JSDOM('<body><select class="msel"><option>- pick -</option><option>Llama-3.1-8B-Q4.gguf</option><option>LFM2-1.2B-Q8.gguf</option><option>Qwen3-4B-Q5.gguf</option><option>Mistral-7B-Q4.gguf</option><option>LFM2-VL-3B.gguf</option></select><select class="plain"><option>a</option></select></body>', {runScripts: "outside-only", pretendToBeVisual: true});
const w = dom.window; w.ResizeObserver = class { observe() {} };
w.eval("var trace=function(){}; var $=function(id){return window.document.getElementById(id);};" + fs.readFileSync(%r, "utf8") + "; enhanceSelects(document);");
const wrap = w.document.querySelector(".selwrap.msel"), q = wrap.querySelector(".selq"), sel = wrap.querySelector("select");
let changed = 0; sel.addEventListener("change", () => changed++);
const vis = () => [...wrap.querySelectorAll(".selopt")].filter(d => d.style.display !== "none").map(d => d.textContent);
const out = [];
out.push(!!q && !w.document.querySelector(".selwrap.plain .selq"));
out.push(wrap.querySelector(".selsearch").nextElementSibling.className === "selbtn");
q.value = "lfm"; q.dispatchEvent(new w.Event("input", {bubbles: true}));
out.push(wrap.classList.contains("on") && vis().join(",") === "LFM2-1.2B-Q8.gguf,LFM2-VL-3B.gguf");
q.value = "q4"; q.dispatchEvent(new w.Event("input", {bubbles: true}));
q.dispatchEvent(new w.KeyboardEvent("keydown", {key: "Enter", bubbles: true}));
out.push(sel.value === "Llama-3.1-8B-Q4.gguf" && changed === 1 && !wrap.classList.contains("on") && q.value === "" && vis().length === 6);
q.value = "zzz"; q.dispatchEvent(new w.Event("input", {bubbles: true})); out.push(vis().length === 0);
w.eval("selClose(null)"); out.push(q.value === "" && vis().length === 6);
process.stdout.write(out.join("|"));
"""
    _r146 = _sp40.run(["node", "-e", _drv146 % (os.path.join(JSDOM_CWD, "node_modules", "jsdom"), _sf146)],
                      capture_output=True, timeout=60, cwd=JSDOM_CWD)
    check(_r146.stdout.decode().strip() == "true|true|true|true|true|true",
          "run: the field is built into the model picker and not the plain one, "
          "sits above the bar, lfm narrows to the two LFM files and opens the menu, "
          "Enter on q4 picks the first Q4 file with one change event and clears "
          "and closes, no match leaves no rows, and closing restores every row",
          _r146.stdout.decode()[:120] + _r146.stderr.decode()[:160])
except Exception as _e146x:
    check(False, "the patch146 search run did not RUN", str(_e146x)[:140])

