_sp148 = seg(JS, "function spliceTts(text)", "const THOUGHT = String.fromCodePoint(0x1F4AD);")
check("if (!sp.dlg || sp.at > first) continue;" in _sp148 and "Math.abs(sp.at - first)" not in _sp148,
      "a spoken burst goes under the latest reply completed BEFORE it started - "
      "nearest-by-gap could pick the next reply, and neighbours came out 2, 1, 3")
check('"model": os.path.basename(model_path_for_port(rt.get("server")) or ""),' in py
      and "the model that generated this" in JS,
      "the payload card names the model behind the reply")
try:
    if JSDOM_CWD is None:
        raise RuntimeError("jsdom is not installed and could not be fetched - this run is skipped")
    _a148 = JS.index("const SAID = String.fromCharCode(12336)")
    _b148 = JS.index("/* One spoken line, painted")
    _sf148 = os.path.join(tempfile.mkdtemp(), "splice.js")
    with open(_sf148, "w", encoding="utf-8", errors="surrogatepass") as _f:
        _f.write(JS[_a148:_b148])
    _drv148 = """
const {JSDOM} = require(%r); const fs = require("fs");
const dom = new JSDOM("<body></body>", {runScripts: "outside-only"}); const w = dom.window;
const NL = String.fromCharCode(10), W = String.fromCharCode(12336), S = W + String.fromCharCode(0xFE0F);
w.eval("var lastTtsTail=''; var refTake=function(s){return {line:s};}; var TSTAMP_RX=/^[[][0-9][0-9]:[0-9][0-9]:[0-9][0-9]([.][0-9]+)?[]]/;" + fs.readFileSync(%r, "utf8") + "; window.spliceTts = spliceTts;");
w.eval("lastTtsTail=" + JSON.stringify(["[10:00:01.00] A Ann: " + S + " line one " + S, "[10:00:01.50] x 2.10x realtime (1.0s)",
  "[10:00:04.70] A Ann: " + S + " line two " + S, "[10:00:05.20] x 1.30x realtime (1.0s)",
  "[10:00:06.00] " + String.fromCodePoint(0x1F4AD) + " Ann (thought): " + W + " a storm brews " + W, "[10:00:06.40] x 4.09x realtime (2.0s)"].join(NL)));
const TH = String.fromCodePoint(0x1F4AD);
const term = ["[10:00:00.00] D Dialogue [1236] r1", "[10:00:05.00] D Dialogue [1236] r2", "[10:00:05.00]    |- " + TH + " Ann: " + S + " a storm brews", "[10:00:09.00] D Dialogue [1236] r3"].join(NL);
const out = w.spliceTts(term).split(NL);
const under1 = out.findIndex(l => l.indexOf("line two") >= 0) < out.findIndex(l => /r2$/.test(l));
const once = out.filter(l => l.indexOf("a storm brews") >= 0).length === 1;
const ratio = out.some(l => l.indexOf(TH) >= 0 && l.indexOf("a storm brews") >= 0 && l.indexOf("4.09x") >= 0);
const order = out.map(l => l.indexOf("line one") >= 0 ? 1 : l.indexOf("line two") >= 0 ? 2 : 0).filter(x => x).join("");
process.stdout.write([under1, once, ratio, order].join("|"));
"""
    _r148 = _sp40.run(["node", "-e", _drv148 % (os.path.join(JSDOM_CWD, "node_modules", "jsdom"), _sf148)],
                      capture_output=True, timeout=60, cwd=JSDOM_CWD)
    check(_r148.stdout.decode().strip() == "true|true|true|12",
          "run: a line spoken just before the next reply landed sits under the reply "
          "that produced it, the dashboard's thought appears once and carries its "
          "ratio, and spoken lines keep log order",
          _r148.stdout.decode()[:100] + _r148.stderr.decode()[:160])
except Exception as _e148x:
    check(False, "the patch148 splice run did not RUN", str(_e148x)[:140])

