section("v3.76 patch149: combat speaks; reasoning in content is reasoning")
check('SPEECH_TITLES = ("Dialogue", "Combat")' in py and py.count("in SPEECH_TITLES") >= 3,
      "one set of speaking titles, read by the speaker registration, the stream "
      "handler and the completion reorder - each had tested Dialogue alone")
