check('const _t = String(lab).split("' + chr(9) + '");' in JS
      and "ttsTitle(_t[0], _t[1]).replace('</label>'" in JS,
      "and Folder Settings SPLITS its titles from their descriptions - p170 put the "
      "tab form in the table and this line still printed the whole string, tab and "
      "all, so the page looked exactly as it had. Half a change is no change")
try:
    _d174 = tempfile.mkdtemp()
    _kf174, _km174 = fp._KIND["file"], fp._KIND["map"]
    try:
        fp._KIND["file"] = os.path.join(_d174, "k.json")
        fp._KIND["map"] = {"_rules": fp._KIND_RULES}
        def _kv174(k, v):
            return (struct.pack("<Q", len(k)) + k.encode() + struct.pack("<I", 8)
                    + struct.pack("<Q", len(v)) + v.encode())
        _b174 = (b"GGUF" + struct.pack("<I", 3) + struct.pack("<Q", 1)
                 + struct.pack("<Q", 1) + _kv174("general.architecture", "llama"))
        _nm174 = b"blk.0.attn_q.weight"
        _b174 += (struct.pack("<Q", len(_nm174)) + _nm174 + struct.pack("<I", 1)
                  + struct.pack("<Q", 4096) + struct.pack("<I", 0)
                  + struct.pack("<Q", 1 << 20))
        _p174 = os.path.join(_d174, "arriving.gguf")
        with open(_p174, "wb") as _f:
            _f.write(_b174 + b"\x00" * 64)
        _sig1 = fp._models_sig([_d174])
        _r1 = fp.model_facts(_p174)
        _rec = fp._kind_map(fp._KIND)[fp._kind_key(_p174)]
        _said = int(_rec.get("_size") or 0)
        with open(_p174, "r+b") as _f:
            _f.truncate((1 << 20) + 8192)
        os.utime(_p174, (time.time() + 2, time.time() + 2))
        _sig2 = fp._models_sig([_d174])
        _stale = fp._kind_stale(_rec, os.stat(_p174))
        _r2 = fp.model_facts(_p174)
    finally:
        fp._KIND["file"], fp._KIND["map"] = _kf174, _km174
        shutil.rmtree(_d174, ignore_errors=True)
    check(not fp._facts_complete(_r1) and _said < 1000 and _sig1 != _sig2
          and _stale and fp._facts_complete(_r2) and _r2.get("arch") == "llama",
          "run: a file read while it is still arriving is recorded as the SHORT file "
          "it was, the folder fingerprint moves when it finishes, the record goes "
          "stale, and the next read succeeds - the whole loop, with no timer in it",
          "%r %r %r %r %r" % (fp._facts_complete(_r1), _said, _sig1 != _sig2,
                              _stale, _r2.get("arch")))
except Exception as _e174x:
    check(False, "the patch174 arrival run did not RUN", str(_e174x)[:140])

