    check(_tie181 == [2030, 2031, 2031, 2030],
          "run: a sentence both replies still hold unspoken goes to the OLDER reply first, "
          "the next one to the newer, and each reply's own remaining lines stay its own",
          str(_tie181))
    # an open entry nobody closed expires at the next settle after ten minutes
    fp.speech_live_open(2099, "Ghost"); fp.SPEECH_LIVE[2099]["t0"] -= 601
    fp.speech_live_close(2100, "Guard", "Halt.")
    check(2099 not in fp.SPEECH_LIVE, "run: a stream nobody closed in ten minutes is dropped at the next close")
