    _ss195, _ts195, _fa195 = fp.slot_status, fp.tts_server_status, fp.FLEET_ACT["n"]
    _cfg195 = {"slots": [{"id": "a", "name": "Chat", "params": {"port": 5001}}, {"id": "b", "name": "Vision", "params": {"port": 5002}}], "settings": {}}
    fp.slot_status = lambda port: {"state": {5001: "serving", 5002: "down"}.get(port, "down")}
    fp.tts_server_status = lambda cfg=None: {"state": "down", "pid": None, "stopping": False}
    _a = fp.llama_servers_up(_cfg195) == ["Chat (serving)"] and fp.tts_server_up(_cfg195) == []
    fp.slot_status = lambda port: {"state": "down"}
    _b = fp.llama_servers_up(_cfg195) == []
    fp.FLEET_ACT["n"] = 1
    _c = fp.llama_servers_up(_cfg195) == ["a launch or stop still in progress"]
    fp.FLEET_ACT["n"] = 0
    fp.tts_server_status = lambda cfg=None: {"state": "down", "pid": None, "stopping": True}
    _d = fp.tts_server_up(_cfg195) == ["the TTS server (stopping)"]
    fp.tts_server_status = lambda cfg=None: {"state": "down", "pid": 77, "stopping": False}
    _e = fp.tts_server_up(_cfg195) == ["the TTS server (starting)"]
    fp.tts_server_status = lambda cfg=None: {"state": "serving", "pid": 77, "stopping": False}
    _f = fp.llama_servers_up(_cfg195) == []          # a TTS server up is NOT a llama.cpp server up
    check(_a and _b and _c and _d and _e and _f,
          "run: the llama guard names the slot that serves and nothing when all are down, counts a "
          "launch or stop in flight, and the TTS guard names its server starting, serving or "
          "stopping - and with the TTS server serving and every slot down the llama guard names "
          "nothing: each guard sees only its own server")
    # refusals only: a call that is NOT refused starts a real install thread, which
    # the gate must never do - "not by the other server" is proven on the guards above
    fp.slot_status = lambda port: {"state": "serving"}
    fp.tts_server_status = lambda cfg=None: {"state": "down", "pid": None, "stopping": False}
