    _d1 = fp.api_higgs_install({"action": "dismiss"})
    fp.slot_status = lambda port: {"state": "down"}
    fp.tts_server_status = lambda cfg=None: {"state": "serving", "pid": 123, "stopping": False}
    _r3 = fp.api_higgs_install({"confirm": True, "tts": "acpp", "parts": "engine"})
    _u4 = fp.api_llama_install({})
    check("shut them down first" in str(_r1.get("error")) and _d1 == {"ok": True}
          and "stop it first" in str(_r3.get("error")) and _u4.get("error") == "not confirmed",
          "run: the llama.cpp install is refused while a slot serves; dismiss still answers ok; the "
          "audio.cpp install is refused while the TTS server is up; an unconfirmed llama.cpp install "
          "answers 'not confirmed' before any guard - the guard sits at the install itself")
